insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_ree_beach', 'https://downloads.bbc.co.uk/learningenglish/realeasyenglish/260529_REE_the_beach_download.mp3', 386,
  '[{"speaker":"Neil","text":"Hello and welcome to Real Easy English.","startMs":220,"endMs":3100},{"speaker":"Neil","text":"We''re back with another conversation in easy English to help you learn.","startMs":3440,"endMs":7500},{"speaker":"Becca","text":"And you can find a video version of this podcast on our website that comes with subtitles to help your learning.","startMs":9660,"endMs":16180},{"speaker":"Becca","text":"That''s at bbclearningenglish.","startMs":16560,"endMs":19360},{"speaker":"Neil","text":"Hi Becca. How are you?","startMs":26860,"endMs":27980},{"speaker":"Becca","text":"I''m really well, thank you, Neil.","startMs":28100,"endMs":29580},{"speaker":"Neil","text":"You look very relaxed, though.","startMs":32540,"endMs":34130},{"speaker":"Neil","text":"So, what have you been doing?","startMs":34130,"endMs":36040},{"speaker":"Becca","text":"Well, I''ve recently been to the beach.","startMs":36360,"endMs":39590},{"speaker":"Becca","text":"to visit my parents, and they live quite close to the beach, so that''s probably why I look and feel very relaxed.","startMs":40620,"endMs":50140},{"speaker":"Neil","text":"Well, we are talking about the beach today.","startMs":51600,"endMs":54340},{"speaker":"Neil","text":"Becca, when you have a beach day, do you like to sunbathe, which means lying on the beach in the Sun doing nothing, or do you prefer to do something active, like swimming?","startMs":55880,"endMs":72200},{"speaker":"Neil","text":"People often play sports on the beach – that kind of thing.","startMs":72640,"endMs":76420},{"speaker":"Becca","text":"I do love to sunbathe, but we don''t have a lot of sun in the UK, and the temperatures aren''t always the best for sunbathing.","startMs":76420,"endMs":88860},{"speaker":"Becca","text":"But it''s still something I really enjoy doing.","startMs":88860,"endMs":92460},{"speaker":"Becca","text":"I''ll sunbathe for a little bit.","startMs":92800,"endMs":95000},{"speaker":"Becca","text":"I''ll cook under the Sun and then I''ll go for a swim to cool down.","startMs":96220,"endMs":102460},{"speaker":"Becca","text":"But yeah, I prefer more relaxing activities.","startMs":102960,"endMs":105760},{"speaker":"Becca","text":"I know some people enjoy, like, beach volleyball, or some people like long, long coastal walks.","startMs":106100,"endMs":116200},{"speaker":"Becca","text":"But yeah, I prefer, kind of, just staying in one spot and relaxing there.","startMs":116280,"endMs":121740},{"speaker":"Neil","text":"I prefer to do something active at the beach.","startMs":122880,"endMs":127300},{"speaker":"Neil","text":"I like to play beach football, beach cricket...","startMs":129260,"endMs":131740},{"speaker":"Becca","text":"Ooh!","startMs":131740,"endMs":133580},{"speaker":"Neil","text":"And if I am lying or sunbathing, I like to read a book.","startMs":133580,"endMs":139800},{"speaker":"Becca","text":"Yeah.","startMs":140860,"endMs":141000},{"speaker":"Neil","text":"it''s a bit uncomfortable.","startMs":141060,"endMs":141960},{"speaker":"Becca","text":"It can be uncomfortable.","startMs":143760,"endMs":145080},{"speaker":"Becca","text":"Also, you mentioned that you like playing some sports on the beach.","startMs":146840,"endMs":149760},{"speaker":"Becca","text":"I imagine it can be quite difficult to play sports on a pebbly beach.","startMs":150220,"endMs":156060},{"speaker":"Becca","text":"Pebbles are small stones, and very different to sandy beaches.","startMs":156700,"endMs":161740},{"speaker":"Becca","text":"Sand is quite soft and, I guess, easier for beach football and beach cricket.","startMs":161880,"endMs":166580},{"speaker":"Neil","text":"Yeah, lots of the beaches in the UK are pebble beaches with stones on them rather than sand.","startMs":167960,"endMs":174820},{"speaker":"Neil","text":"And yes, it can be more difficult.","startMs":175040,"endMs":178230},{"speaker":"Neil","text":"It can really hurt your feet.","startMs":178230,"endMs":180260},{"speaker":"Becca","text":"Sometimes it is quite funny on a pebbly beach to see people coming out of the sea from their swim and then, kind of, you know, finding it quite difficult to walk along the beach.","startMs":180840,"endMs":192520},{"speaker":"Becca","text":"It sometimes is quite funny.","startMs":193920,"endMs":195340},{"speaker":"Neil","text":"So, do you take a picnic to the beach?","startMs":198460,"endMs":200660},{"speaker":"Becca","text":"Another reason, actually...","startMs":202200,"endMs":203820},{"speaker":"Becca","text":"We talked about pebbly beaches.","startMs":204000,"endMs":206360},{"speaker":"Becca","text":"But I really love a pebble beach because it''s easier to have a picnic on a pebble beach.","startMs":206740,"endMs":213420},{"speaker":"Becca","text":"I don''t know about your own experiences, but every time I sit on a sandy beach with a lovely picnic, it always gets ruined by all of the sand.","startMs":213420,"endMs":224740},{"speaker":"Neil","text":"You end up with a kind of crunchy sandwich.","startMs":225740,"endMs":229040},{"speaker":"Becca","text":"Yeah. Sandy sandwiches.","startMs":229120,"endMs":230560},{"speaker":"Neil","text":"Sandy, sandy sandwiches!","startMs":232000,"endMs":233000},{"speaker":"Becca","text":"So, I do love a picnic on the beach.","startMs":234480,"endMs":237080},{"speaker":"Becca","text":"But, yeah, you do have to be careful about where you are, and the wind as well.","startMs":237080,"endMs":243700},{"speaker":"Neil","text":"Yes, especially in the UK.","startMs":243800,"endMs":245900},{"speaker":"Becca","text":"Mmm. Yeah.","startMs":246100,"endMs":246680},{"speaker":"Neil","text":"Because they''re quite windy.","startMs":246880,"endMs":247730},{"speaker":"Becca","text":"Very windy in the UK.","startMs":247730,"endMs":248940},{"speaker":"Neil","text":"But the world is full of beautiful beaches.","startMs":249140,"endMs":253200},{"speaker":"Neil","text":"Have you got a memory of a favourite beach you''ve been to somewhere?","startMs":253920,"endMs":257480},{"speaker":"Becca","text":"Yes, I have beautiful memories.","startMs":258120,"endMs":262180},{"speaker":"Becca","text":"Probably the most recent and the most beautiful was when I was in Thailand last February.","startMs":262360,"endMs":269120},{"speaker":"Becca","text":"Very cold and rainy in the UK, so I decided to go to Thailand, and I just remember seeing the sunset at the beach, and I''d never seen the Sun so red before.","startMs":270040,"endMs":284220},{"speaker":"Becca","text":"So, when the Sun is setting and it''s, kind of...","startMs":285540,"endMs":287610},{"speaker":"Becca","text":"it looks like it''s going below sea level, at night time.","startMs":287610,"endMs":292880},{"speaker":"Neil","text":"Time now to recap the vocabulary we''ve heard in this podcast, starting with sunbathe.","startMs":303340,"endMs":309500},{"speaker":"Neil","text":"If you sunbathe, you sit or lie in the sunshine to relax.","startMs":310000,"endMs":314810},{"speaker":"Neil","text":"But you have to be careful in case you get burnt.","startMs":314810,"endMs":318220},{"speaker":"Becca","text":"Yes, and if you sunbathe for too long, you might need to cool down.","startMs":318920,"endMs":323400},{"speaker":"Becca","text":"To cool down means to do something to cool yourself when you''re feeling too hot.","startMs":323740,"endMs":329600},{"speaker":"Becca","text":"And you can do that by going for a swim.","startMs":329880,"endMs":331820},{"speaker":"Becca","text":"And to go for a swim is to literally go swimming, but it could also mean just to relax in the water.","startMs":332000,"endMs":339200},{"speaker":"Neil","text":"We talked about two different kinds of beaches – pebble beaches and sandy beaches.","startMs":339960,"endMs":345740},{"speaker":"Neil","text":"Pebble beaches are covered in small, smooth stones.","startMs":346260,"endMs":351500},{"speaker":"Neil","text":"They can be difficult to walk on.","startMs":352000,"endMs":353660},{"speaker":"Neil","text":"A sandy beach is covered in sand, and sand is that fine grain and it''s much more comfortable to walk on.","startMs":353880,"endMs":361960},{"speaker":"Becca","text":"And lastly, we mentioned picnics.","startMs":362860,"endMs":365350},{"speaker":"Becca","text":"A picnic is a meal that you enjoy outside.","startMs":365350,"endMs":368960},{"speaker":"Neil","text":"That''s it for this episode of Real Easy English, but don''t forget to go to our website to download a free worksheet.","startMs":370000,"endMs":376850},{"speaker":"Neil","text":"That''s at bbclearningenglish.","startMs":376850,"endMs":379320},{"speaker":"Becca","text":"And we''ll be back next week with another episode of Real Easy English.","startMs":379840,"endMs":384460},{"speaker":"Neil","text":"Goodbye.","startMs":385480,"endMs":385800}]'::jsonb,
  'Understand and discuss talking about the beach using BBC natural English. You''ll pick up useful words like sunbathe, cool down, pebble beach. Listen to Neil & Becca talk it through in natural English.',
  '["We''re back with another conversation in easy English to help you learn.","And you can find a video version of this podcast on our website that comes with subtitles to help your learning.","to visit my parents, and they live quite close to the beach, so that''s probably why I look and feel very relaxed."]'::jsonb,
  '[{"word":"sunbathe","phonetic":"","pos":"Verb","translation":"quyoshda toblanmoq","definition":"to sit or lie in the sun to relax","example":"Becca, when you have a beach day, do you like to sunbathe, which means lying on the beach in the Sun doing nothing, or do you prefer to do something active, like swimming?"},{"word":"cool down","phonetic":"","pos":"Phrasal verb","translation":"sovimoq","definition":"to become cooler after being hot","example":"I''ll cook under the Sun and then I''ll go for a swim to cool down."},{"word":"pebble beach","phonetic":"","pos":"Noun phrase","translation":"mayda toshli plyaj","definition":"a beach covered in small smooth stones","example":"Pebbles are small stones, and very different to sandy beaches."},{"word":"sandy beach","phonetic":"","pos":"Noun phrase","translation":"qumli plyaj","definition":"a beach covered with sand","example":"Pebbles are small stones, and very different to sandy beaches."},{"word":"picnic","phonetic":"","pos":"Noun","translation":"piknik","definition":"a meal eaten outside","example":"So, do you take a picnic to the beach?"},{"word":"stunning","phonetic":"","pos":"Adjective","translation":"hayratlanarli darajada chiroyli","definition":"extremely beautiful or impressive","example":"We''re back with another conversation in easy English to help you learn."}]'::jsonb,
  '[{"type":"mc","question":"What does \"sunbathe\" mean in this lesson?","options":["to sit or lie in the sun to relax","to become cooler after being hot","a beach covered in small smooth stones","a beach covered with sand"],"correct":0,"explanation":"\"sunbathe\" means: to sit or lie in the sun to relax"},{"type":"mc","question":"What does \"cool down\" mean in this lesson?","options":["to sit or lie in the sun to relax","a beach covered in small smooth stones","a beach covered with sand","to become cooler after being hot"],"correct":3,"explanation":"\"cool down\" means: to become cooler after being hot"},{"type":"mc","question":"What does \"pebble beach\" mean in this lesson?","options":["to become cooler after being hot","a beach covered with sand","a beach covered in small smooth stones","to sit or lie in the sun to relax"],"correct":2,"explanation":"\"pebble beach\" means: a beach covered in small smooth stones"},{"type":"mc","question":"What does \"sandy beach\" mean in this lesson?","options":["a beach covered in small smooth stones","a beach covered with sand","to sit or lie in the sun to relax","to become cooler after being hot"],"correct":1,"explanation":"\"sandy beach\" means: a beach covered with sand"}]'::jsonb,
  'Understand and discuss talking about the beach using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

