insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_ree_names', 'https://downloads.bbc.co.uk/learningenglish/realeasyenglish/260522_REE_names_download.mp3', 325,
  '[{"speaker":"Phil","text":"Hello and welcome to Real Easy English.","startMs":180,"endMs":3820},{"speaker":"Phil","text":"We''re back with another conversation in easy English to help you learn.","startMs":4120,"endMs":8940},{"speaker":"Georgie","text":"You can find a video version of this podcast with subtitles so you can read along.","startMs":11220,"endMs":16680},{"speaker":"Georgie","text":"It''s all on our website.","startMs":17060,"endMs":18340},{"speaker":"Georgie","text":"That''s bbclearningenglish.","startMs":18560,"endMs":18820},{"speaker":"Phil","text":"How are you, Georgie?","startMs":28660,"endMs":29420},{"speaker":"Georgie","text":"I''m very well thank you, Phil.","startMs":29580,"endMs":31280},{"speaker":"Phil","text":"Today we''re going to talk all about names.","startMs":34480,"endMs":38210},{"speaker":"Phil","text":"We''re going to talk about our names and where they come from.","startMs":38210,"endMs":42420},{"speaker":"Georgie","text":"Ooh, it''s an interesting topic.","startMs":42540,"endMs":44420},{"speaker":"Georgie","text":"Phil, what''s the story behind your name?","startMs":45360,"endMs":48360},{"speaker":"Georgie","text":"Were you named after anyone or anything?","startMs":48360,"endMs":50480},{"speaker":"Phil","text":"I don''t know if I''m honest.","startMs":51160,"endMs":52920},{"speaker":"Phil","text":"I don''t know why I have my name.","startMs":53020,"endMs":54960},{"speaker":"Georgie","text":"Yeah, I wish I had a better story for my name, but my parents had friends that had a dog called Georgia, and they liked that name.","startMs":56740,"endMs":68000},{"speaker":"Georgie","text":"And so they decided to call me Georgia, which might be the first time people are hearing that my name – my real name – is Georgia, not Georgie.","startMs":68000,"endMs":77780},{"speaker":"Phil","text":"Ah.","startMs":77780,"endMs":79540},{"speaker":"Georgie","text":"So, I guess I was named after a dog!","startMs":79540,"endMs":82220},{"speaker":"Georgie","text":"So, your name is Philip, but lots of people call you Phil, which is a nickname.","startMs":83880,"endMs":89360},{"speaker":"Georgie","text":"So, a nickname is an informal name given to you by friends and family, which is often a shortened version, like Phil.","startMs":89980,"endMs":97820},{"speaker":"Phil","text":"Yeah, often it''s a shortened name.","startMs":99580,"endMs":101200},{"speaker":"Phil","text":"In my case, that''s the only one that''s ever stuck, that people have ever called me.","startMs":101280,"endMs":107280},{"speaker":"Phil","text":"But you can also sometimes have, like, a jokey, fun name that might not be anything to do with your real name, but your friends call you that.","startMs":107800,"endMs":118280},{"speaker":"Phil","text":"Lots of people have them at school or in your family.","startMs":118520,"endMs":120940},{"speaker":"Phil","text":"Do you have any nicknames, Georgie?","startMs":121960,"endMs":123080},{"speaker":"Georgie","text":"Yes, I have a nickname that my dad calls me, which is Billy, short for Silly Billy because I do lots of stupid things.","startMs":124200,"endMs":134820},{"speaker":"Phil","text":"I''m getting the feeling...","startMs":135760,"endMs":136000},{"speaker":"Phil","text":"Do you like that nickname or...?","startMs":136300,"endMs":137580},{"speaker":"Georgie","text":"I think it''s quite...","startMs":139480,"endMs":142500},{"speaker":"Georgie","text":"I don''t mind it that much.","startMs":142960,"endMs":144400},{"speaker":"Georgie","text":"As long as it''s only my dad that calls me Billy, it''s OK.","startMs":144440,"endMs":148320},{"speaker":"Georgie","text":"Do you like your name?","startMs":149800,"endMs":151160},{"speaker":"Phil","text":"I''ve never thought about it a lot, so I think I do.","startMs":151160,"endMs":157300},{"speaker":"Phil","text":"it''s not an unusual name.","startMs":158600,"endMs":161500},{"speaker":"Phil","text":"I don''t know, it might be difficult to have an unusual name, but I don''t think it''s too common either.","startMs":162540,"endMs":170040},{"speaker":"Phil","text":"It''s not like everyone has it, so...","startMs":170080,"endMs":171840},{"speaker":"Georgie","text":"Yeah.","startMs":171840,"endMs":173100},{"speaker":"Phil","text":"I think that''s perfect for a name.","startMs":173100,"endMs":175020},{"speaker":"Georgie","text":"So Phil, have you ever had to name something, like a child or a pet?","startMs":175920,"endMs":181020},{"speaker":"Georgie","text":"And was it difficult?","startMs":181020,"endMs":182000},{"speaker":"Phil","text":"I had to name two people – two children.","startMs":185120,"endMs":187600},{"speaker":"Phil","text":"For my daughter, my wife was very keen on the name that we gave my daughter, so she...","startMs":188200,"endMs":192920},{"speaker":"Phil","text":"so that was easy for me.","startMs":193300,"endMs":194440},{"speaker":"Phil","text":"For my son, I really wanted a name that worked in English and in Spanish and wasn''t too different.","startMs":195580,"endMs":203240},{"speaker":"Phil","text":"And there''s not actually that many boys'' names that work easily in both languages, or that I could think of.","startMs":204080,"endMs":211220},{"speaker":"Georgie","text":"Yeah, because your wife is from Argentina, so you needed a name that worked in both.","startMs":211300,"endMs":216900},{"speaker":"Phil","text":"Georgie, have you ever had to name something like a pet or someone?","startMs":217800,"endMs":221720},{"speaker":"Georgie","text":"Well, actually, my parents are getting a dog in a few...","startMs":222160,"endMs":226140},{"speaker":"Georgie","text":"in a couple of weeks, and we''re thinking about names right now, so it''s quite a relevant question.","startMs":226140,"endMs":231520},{"speaker":"Georgie","text":"It is difficult, isn''t it?","startMs":231900,"endMs":233720},{"speaker":"Georgie","text":"Because you have to think of a name that you''re going to like for a long time, that you''re not going to get bored of because you use it so much.","startMs":233720,"endMs":242520},{"speaker":"Phil","text":"I guess with dogs'' names, you don''t want to have something that''s too common, because when you call your dog, the whole park will come running to you!","startMs":243120,"endMs":252100},{"speaker":"Georgie","text":"We''re trying to think of something a little bit more unusual and fun.","startMs":254420,"endMs":257860},{"speaker":"Phil","text":"Let''s recap the vocabulary we heard during the conversation, starting with nickname, which is an informal name used by family and friends.","startMs":265040,"endMs":275320},{"speaker":"Georgie","text":"We can use name as a verb, which means to give someone a name.","startMs":275540,"endMs":280240},{"speaker":"Georgie","text":"For example, my parents named me Georgie.","startMs":280340,"endMs":283460},{"speaker":"Phil","text":"If you''re named after something or someone, you''re given the same name as them because of them.","startMs":284080,"endMs":290880},{"speaker":"Phil","text":"For example, Georgie was named after a dog called Georgia.","startMs":291480,"endMs":295800},{"speaker":"Georgie","text":"Your name might be common, which means lots of people have the same name.","startMs":297360,"endMs":302020},{"speaker":"Phil","text":"Or your name might be unusual, and that means that not many people have the same name.","startMs":302600,"endMs":308080},{"speaker":"Phil","text":"That''s it for this episode of Real Easy English.","startMs":309500,"endMs":313360},{"speaker":"Phil","text":"Test what you''ve learned with the worksheet on our website.","startMs":313680,"endMs":317260},{"speaker":"Phil","text":"And that''s bbclearningenglish.","startMs":317380,"endMs":320340},{"speaker":"Georgie","text":"We''ll be back next week with more easy English.","startMs":320600,"endMs":323600},{"speaker":"Phil","text":"Bye!","startMs":324640,"endMs":325040}]'::jsonb,
  'Understand and discuss talking about names using BBC natural English. You''ll pick up useful words like named after, nickname, shortened version. Listen to Phil & Georgie talk it through in natural English.',
  '["We''re back with another conversation in easy English to help you learn.","You can find a video version of this podcast with subtitles so you can read along.","We''re going to talk about our names and where they come from."]'::jsonb,
  '[{"word":"named after","phonetic":"","pos":"Phrase","translation":"nomi ... sharafiga qo‘yilgan","definition":"given the same name as another person, place, or thing","example":"Were you named after anyone or anything?"},{"word":"nickname","phonetic":"","pos":"Noun","translation":"laqab","definition":"an informal name used by friends or family","example":"So, your name is Philip, but lots of people call you Phil, which is a nickname."},{"word":"shortened version","phonetic":"","pos":"Noun phrase","translation":"qisqartirilgan shakl","definition":"a shorter form of a name or word","example":"So, a nickname is an informal name given to you by friends and family, which is often a shortened version, like Phil."},{"word":"unusual","phonetic":"","pos":"Adjective","translation":"odatiy emas","definition":"not common or ordinary","example":"it''s not an unusual name."},{"word":"common","phonetic":"","pos":"Adjective","translation":"keng tarqalgan","definition":"seen or used by many people","example":"I don''t know, it might be difficult to have an unusual name, but I don''t think it''s too common either."},{"word":"identity","phonetic":"","pos":"Noun","translation":"shaxsiyat","definition":"who a person is and how they are known","example":"We''re back with another conversation in easy English to help you learn."}]'::jsonb,
  '[{"type":"mc","question":"What does \"named after\" mean in this lesson?","options":["given the same name as another person, place, or thing","an informal name used by friends or family","a shorter form of a name or word","not common or ordinary"],"correct":0,"explanation":"\"named after\" means: given the same name as another person, place, or thing"},{"type":"mc","question":"What does \"nickname\" mean in this lesson?","options":["given the same name as another person, place, or thing","a shorter form of a name or word","not common or ordinary","an informal name used by friends or family"],"correct":3,"explanation":"\"nickname\" means: an informal name used by friends or family"},{"type":"mc","question":"What does \"shortened version\" mean in this lesson?","options":["an informal name used by friends or family","not common or ordinary","a shorter form of a name or word","given the same name as another person, place, or thing"],"correct":2,"explanation":"\"shortened version\" means: a shorter form of a name or word"},{"type":"mc","question":"What does \"unusual\" mean in this lesson?","options":["a shorter form of a name or word","not common or ordinary","given the same name as another person, place, or thing","an informal name used by friends or family"],"correct":1,"explanation":"\"unusual\" means: not common or ordinary"}]'::jsonb,
  'Understand and discuss talking about names using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

