insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_ree_diy', 'https://downloads.bbc.co.uk/learningenglish/realeasyenglish/260515_REE_DIY_download.mp3', 352,
  '[{"speaker":"Georgie","text":"Hello and welcome to Real Easy English.","startMs":100,"endMs":3100},{"speaker":"Georgie","text":"We''re back with another conversation in easy English to help you learn.","startMs":3260,"endMs":7560},{"speaker":"Phil","text":"And you can find a video version of this podcast with subtitles to help you on our website.","startMs":9920,"endMs":16360},{"speaker":"Phil","text":"And that''s at bbclearningenglish.","startMs":16360,"endMs":19620},{"speaker":"Georgie","text":"Hello Phil. How are you?","startMs":26400,"endMs":27980},{"speaker":"Phil","text":"I''m good, but I''m also a little bit tired because I''ve been doing DIY all weekend.","startMs":28500,"endMs":36180},{"speaker":"Georgie","text":"Well, that''s lucky because today we''re talking about DIY.","startMs":37100,"endMs":41160},{"speaker":"Georgie","text":"DIY stands for Do It Yourself and it means doing things to your home, such as fixing and painting.","startMs":41700,"endMs":49400},{"speaker":"Georgie","text":"So, what kind of DIY have you been doing this weekend?","startMs":50280,"endMs":53940},{"speaker":"Phil","text":"Yes, I''ve been trying to fix my water tank.","startMs":54620,"endMs":57860},{"speaker":"Georgie","text":"And do you do a lot of DIY?","startMs":59300,"endMs":61940},{"speaker":"Phil","text":"I''m not very good at DIY.","startMs":66600,"endMs":69300},{"speaker":"Phil","text":"If it''s something I can do, I will try and do it.","startMs":70140,"endMs":74600},{"speaker":"Phil","text":"Some things I would never touch, like electrics.","startMs":74860,"endMs":78480},{"speaker":"Phil","text":"I wouldn''t go anywhere near that or gas because it''s not safe.","startMs":78960,"endMs":82720},{"speaker":"Phil","text":"But if it''s something that looks safe and I think I can do it, I will try it.","startMs":83760,"endMs":90400},{"speaker":"Georgie","text":"So, what kinds of things do you do around the house?","startMs":91180,"endMs":94900},{"speaker":"Phil","text":"It could be things like painting and decorating your house, making it look nice – that I quite like.","startMs":97000,"endMs":102880},{"speaker":"Phil","text":"Sometimes fixing things with bits of wood that need to go somewhere – I can do that.","startMs":106420,"endMs":113100},{"speaker":"Phil","text":"Putting up fences – I could do that, but that''s probably it.","startMs":114840,"endMs":120260},{"speaker":"Phil","text":"What about you, Georgie?","startMs":121480,"endMs":122380},{"speaker":"Georgie","text":"I actually rent my flat, so that means I can''t really do much to the place because it''s not mine.","startMs":127060,"endMs":133200},{"speaker":"Georgie","text":"But recently I have put up some lights in my room, because I changed rooms, so I''ve put up some nice fairy lights on the wall, and I''ve put up some frames with art and photos, so that''s probably my limit.","startMs":134000,"endMs":152040},{"speaker":"Georgie","text":"I wouldn''t do anything else.","startMs":152220,"endMs":153900},{"speaker":"Phil","text":"Do you enjoy DIY?","startMs":154620,"endMs":156280},{"speaker":"Georgie","text":"No, I don''t, because I''m quite a lazy person.","startMs":157100,"endMs":161840},{"speaker":"Georgie","text":"So, if I see that something is broken or needs fixing, I will just ignore it – procrastinate, which means to delay something, postpone it – and wait for someone else to do it.","startMs":162260,"endMs":176400},{"speaker":"Georgie","text":"I kind of get used to things being broken and forget that it''s like that.","startMs":176500,"endMs":181920},{"speaker":"Georgie","text":"So, yeah, I''m just a bit lazy.","startMs":183320,"endMs":185380},{"speaker":"Georgie","text":"Phil, have you ever put together furniture, like flat-pack furniture?","startMs":186020,"endMs":190940},{"speaker":"Phil","text":"Because, yeah, a lot of furniture you buy that''s fairly cheap – you have to do that.","startMs":195220,"endMs":202520},{"speaker":"Phil","text":"I don''t actually mind that.","startMs":203540,"endMs":208100},{"speaker":"Phil","text":"It''s quite good to do it with someone and you work as a team.","startMs":208300,"endMs":212780},{"speaker":"Georgie","text":"Mmm. Like an activity?","startMs":212840,"endMs":214200},{"speaker":"Phil","text":"Well, sometimes it''s fun.","startMs":217340,"endMs":218660},{"speaker":"Phil","text":"Sometimes it''s stressful.","startMs":218700,"endMs":219700},{"speaker":"Georgie","text":"If it goes well that can be a nice thing to do with someone, but if it goes badly it could lead to an argument.","startMs":220700,"endMs":227960},{"speaker":"Georgie","text":"Do you have any big plans for your house?","startMs":228500,"endMs":231040},{"speaker":"Phil","text":"I would really like to get a very nice bit of wood and make a nice bar for my kitchen.","startMs":231220,"endMs":238200},{"speaker":"Phil","text":"I''d love to do that, but it''s expensive and I haven''t done it yet.","startMs":239000,"endMs":242900},{"speaker":"Phil","text":"I keep procrastinating and not doing it.","startMs":242960,"endMs":245620},{"speaker":"Georgie","text":"I rent my flat so I can''t do anything big.","startMs":248120,"endMs":250720},{"speaker":"Georgie","text":"I don''t have big plans, but we do have an outdoor terrace, which at the moment it''s not very...","startMs":250740,"endMs":259160},{"speaker":"Georgie","text":"it''s not in a very good state.","startMs":259160,"endMs":260740},{"speaker":"Georgie","text":"So, I would like to clean it, maybe get some plants for it.","startMs":261000,"endMs":266120},{"speaker":"Georgie","text":"I''d like to put some lights out there, actually, so that when people come round it will be really nice in the evenings.","startMs":266140,"endMs":273520},{"speaker":"Georgie","text":"So, yeah, that''s my plan.","startMs":274400,"endMs":275520},{"speaker":"Georgie","text":"Ready for the summer.","startMs":275600,"endMs":276780},{"speaker":"Phil","text":"That sounds lovely.","startMs":277420,"endMs":278160},{"speaker":"Georgie","text":"Let''s recap the language we heard during the conversation, starting with DIY, which stands for Do It Yourself.","startMs":285920,"endMs":293040},{"speaker":"Georgie","text":"These are jobs you do around the house, like fixing or painting.","startMs":293500,"endMs":297200},{"speaker":"Georgie","text":"For example, I don''t like DIY – I''m too lazy.","startMs":297560,"endMs":300600},{"speaker":"Phil","text":"We also heard decorate, which means paint a room or change how it looks.","startMs":301360,"endMs":306820},{"speaker":"Georgie","text":"We heard flat-pack furniture, which is furniture which comes with instructions so that you can build it yourself.","startMs":307040,"endMs":313480},{"speaker":"Phil","text":"And we heard a couple of phrasal verbs.","startMs":314560,"endMs":317180},{"speaker":"Phil","text":"If you put something up, you fix it to the wall.","startMs":317620,"endMs":321020},{"speaker":"Phil","text":"So, for example, Georgie put up some picture frames in her bedroom.","startMs":321200,"endMs":325120},{"speaker":"Georgie","text":"And if you put something together, you build it.","startMs":325520,"endMs":328600},{"speaker":"Georgie","text":"For example, Phil likes to put together flat-pack furniture with someone else.","startMs":328740,"endMs":333340},{"speaker":"Phil","text":"And that''s it for this episode of Real Easy English.","startMs":334360,"endMs":338380},{"speaker":"Phil","text":"You can practise what you''ve learnt with a worksheet that''s on our website, bbclearningenglish.","startMs":338900,"endMs":346040},{"speaker":"Georgie","text":"And we''ll be back next week with another conversation in easy English.","startMs":346160,"endMs":350840},{"speaker":"Phil","text":"Bye!","startMs":351900,"endMs":352380}]'::jsonb,
  'Understand and discuss talking about diy using BBC natural English. You''ll pick up useful words like DIY, water tank, electrics. Listen to Georgie & Phil talk it through in natural English.',
  '["We''re back with another conversation in easy English to help you learn.","And you can find a video version of this podcast with subtitles to help you on our website.","I''m good, but I''m also a little bit tired because I''ve been doing DIY all weekend."]'::jsonb,
  '[{"word":"DIY","phonetic":"","pos":"Noun","translation":"uy ishlarini o‘zi qilish","definition":"doing repairs or improvements at home yourself","example":"I''m good, but I''m also a little bit tired because I''ve been doing DIY all weekend."},{"word":"water tank","phonetic":"","pos":"Noun","translation":"suv baki","definition":"a container that stores water","example":"Yes, I''ve been trying to fix my water tank."},{"word":"electrics","phonetic":"","pos":"Noun","translation":"elektr tizimi","definition":"electrical systems or wiring","example":"Some things I would never touch, like electrics."},{"word":"put up","phonetic":"","pos":"Phrasal verb","translation":"o‘rnatmoq","definition":"to fix something to a wall or position","example":"Putting up fences – I could do that, but that''s probably it."},{"word":"procrastinate","phonetic":"","pos":"Verb","translation":"kechiktirmoq","definition":"to delay doing something","example":"So, if I see that something is broken or needs fixing, I will just ignore it – procrastinate, which means to delay something, postpone it – and wait for someone else to do it."},{"word":"flat-pack furniture","phonetic":"","pos":"Noun phrase","translation":"yig‘iladigan mebel","definition":"furniture sold in pieces that you assemble yourself","example":"We''re back with another conversation in easy English to help you learn."}]'::jsonb,
  '[{"type":"mc","question":"What does \"DIY\" mean in this lesson?","options":["doing repairs or improvements at home yourself","a container that stores water","electrical systems or wiring","to fix something to a wall or position"],"correct":0,"explanation":"\"DIY\" means: doing repairs or improvements at home yourself"},{"type":"mc","question":"What does \"water tank\" mean in this lesson?","options":["doing repairs or improvements at home yourself","electrical systems or wiring","to fix something to a wall or position","a container that stores water"],"correct":3,"explanation":"\"water tank\" means: a container that stores water"},{"type":"mc","question":"What does \"electrics\" mean in this lesson?","options":["a container that stores water","to fix something to a wall or position","electrical systems or wiring","doing repairs or improvements at home yourself"],"correct":2,"explanation":"\"electrics\" means: electrical systems or wiring"},{"type":"mc","question":"What does \"put up\" mean in this lesson?","options":["electrical systems or wiring","to fix something to a wall or position","doing repairs or improvements at home yourself","a container that stores water"],"correct":1,"explanation":"\"put up\" means: to fix something to a wall or position"}]'::jsonb,
  'Understand and discuss talking about diy using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

