insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_ree_fruit', 'https://downloads.bbc.co.uk/learningenglish/realeasyenglish/260508_REE_fruit__download.mp3', 348,
  '[{"speaker":"Becca","text":"Hello and welcome to Real Easy English, where we have easy conversations to help you with your listening skills and learn new vocabulary.","startMs":380,"endMs":9240},{"speaker":"Neil","text":"If you''d like to see a video version of this podcast, you can find it on our website at bbclearningenglish.","startMs":11320,"endMs":18820},{"speaker":"Neil","text":"The video has subtitles, which can help you learn.","startMs":18820,"endMs":21640},{"speaker":"Becca","text":"How are you doing today?","startMs":29600,"endMs":30600},{"speaker":"Neil","text":"I feel great because I just ate a banana.","startMs":32380,"endMs":35140},{"speaker":"Becca","text":"You started off your day quite healthily this morning.","startMs":38300,"endMs":41050},{"speaker":"Neil","text":"Yes, I saw you eating your banana, and I thought, I''m going to eat a banana.","startMs":42560,"endMs":46490},{"speaker":"Becca","text":"Yes, bananas are delicious.","startMs":47950,"endMs":49840},{"speaker":"Becca","text":"And today we are actually talking about fruit.","startMs":50640,"endMs":52880},{"speaker":"Neil","text":"We are, yes, and I love eating fruit.","startMs":53120,"endMs":56080},{"speaker":"Becca","text":"Me too.","startMs":56120,"endMs":57320},{"speaker":"Neil","text":"What kind of fruit do you like?","startMs":57500,"endMs":59060},{"speaker":"Becca","text":"Ooh, besides bananas, I really love berries.","startMs":60220,"endMs":64500},{"speaker":"Becca","text":"And I like green apples and red grapes.","startMs":65140,"endMs":72080},{"speaker":"Becca","text":"I like lots of fruit.","startMs":72140,"endMs":73690},{"speaker":"Neil","text":"Yeah, I really like fruit.","startMs":74940,"endMs":76520},{"speaker":"Neil","text":"I try to eat fruit every day and, like you, I like apples but not just green ones.","startMs":76520,"endMs":84160},{"speaker":"Neil","text":"The red ones – I like those too.","startMs":84540,"endMs":86440},{"speaker":"Neil","text":"And I like frozen berries with my breakfast.","startMs":88700,"endMs":92820},{"speaker":"Becca","text":"So, you mentioned oranges.","startMs":93120,"endMs":95080},{"speaker":"Becca","text":"Oranges can be a little sweet, but they''re actually more sour, aren''t they?","startMs":95340,"endMs":100680},{"speaker":"Neil","text":"Yeah. Sour or sharp.","startMs":100900,"endMs":102540},{"speaker":"Becca","text":"Sharp, yeah.","startMs":102620,"endMs":103740},{"speaker":"Neil","text":"That''s the taste that you get from fruit like oranges, and more so with lemons or limes.","startMs":104380,"endMs":113860},{"speaker":"Neil","text":"These are called citrus fruit.","startMs":113880,"endMs":117710},{"speaker":"Becca","text":"They have more of a sour taste.","startMs":117710,"endMs":120000},{"speaker":"Neil","text":"If you bite into a lemon, that''s sour.","startMs":120620,"endMs":124160},{"speaker":"Becca","text":"The face that you make....","startMs":124780,"endMs":126160},{"speaker":"Neil","text":"Yeah.","startMs":126160,"endMs":126161},{"speaker":"Becca","text":"when you bite into something citrus, yeah.","startMs":126160,"endMs":129100},{"speaker":"Becca","text":"Do you prefer sweet fruit or sour fruit?","startMs":129340,"endMs":132280},{"speaker":"Neil","text":"Yeah, I like sweet fruit.","startMs":132560,"endMs":134280},{"speaker":"Neil","text":"And probably I like fruit when it''s ripe.","startMs":134440,"endMs":138640},{"speaker":"Becca","text":"What does that mean – ripe?","startMs":139830,"endMs":140960},{"speaker":"Neil","text":"It means that it''s ready to eat.","startMs":141420,"endMs":143440},{"speaker":"Neil","text":"It''s at its sweetest usually, probably quite juicy.","startMs":143600,"endMs":148660},{"speaker":"Neil","text":"If fruit is juicy, it means juice comes from it.","startMs":148920,"endMs":153060},{"speaker":"Neil","text":"And juice is a liquid – watery.","startMs":153060,"endMs":156280},{"speaker":"Neil","text":"If it''s ripe, it''s just before it goes bad or goes off.","startMs":159500,"endMs":163910},{"speaker":"Becca","text":"So, if we''re thinking about bananas, for example, a green-coloured banana perhaps isn''t ready to eat.","startMs":166420,"endMs":171890},{"speaker":"Becca","text":"It''s not ripe like a yellow banana.","startMs":171890,"endMs":173740},{"speaker":"Neil","text":"Yeah, but a yellow one with, sort of, brown bits on it.","startMs":174100,"endMs":177920},{"speaker":"Neil","text":"That''s a ripe banana.","startMs":177920,"endMs":179160},{"speaker":"Becca","text":"Yeah, they''re a bit too sweet for me.","startMs":179520,"endMs":182100},{"speaker":"Becca","text":"I kind of like that middle...","startMs":182100,"endMs":184480},{"speaker":"Becca","text":"Yeah, I like yellow bananas.","startMs":184480,"endMs":186580},{"speaker":"Neil","text":"How about dried fruit?","startMs":187440,"endMs":189310},{"speaker":"Neil","text":"Do you like dried fruit?","startMs":189310,"endMs":190560},{"speaker":"Becca","text":"Oh, I''m glad you asked.","startMs":190760,"endMs":192200},{"speaker":"Becca","text":"Yes, I really like dried fruit.","startMs":192260,"endMs":195000},{"speaker":"Becca","text":"So, I will often have raisins.","startMs":195520,"endMs":199440},{"speaker":"Becca","text":"So, raisins are dried grapes.","startMs":199560,"endMs":202240},{"speaker":"Becca","text":"And dried means that it doesn''t have any of that juice or liquid.","startMs":202480,"endMs":206300},{"speaker":"Neil","text":"So, Becca, here is a really important and interesting question.","startMs":207220,"endMs":211420},{"speaker":"Neil","text":"If you could only eat one fruit for the rest of your life, which would you choose?","startMs":211760,"endMs":217180},{"speaker":"Becca","text":"Ooh, that is a very difficult question.","startMs":218220,"endMs":220500},{"speaker":"Becca","text":"We''ve talked a lot about the fruit that we love.","startMs":220560,"endMs":222780},{"speaker":"Becca","text":"But probably bananas because I do eat them every day.","startMs":223940,"endMs":228460},{"speaker":"Becca","text":"It feels quite strange to not eat a banana every day for me.","startMs":228540,"endMs":234300},{"speaker":"Becca","text":"And also I really enjoy banana bread and dried bananas.","startMs":235020,"endMs":239900},{"speaker":"Becca","text":"I completely forgot about those.","startMs":239900,"endMs":241870},{"speaker":"Becca","text":"They''re really tasty.","startMs":241870,"endMs":243000},{"speaker":"Becca","text":"So yeah, there''s lots of things you can do with bananas.","startMs":244140,"endMs":246700},{"speaker":"Becca","text":"What fruit would you choose?","startMs":248840,"endMs":249940},{"speaker":"Neil","text":"I think maybe it sounds boring, but the apple is the perfect snack.","startMs":250280,"endMs":255780},{"speaker":"Neil","text":"You always feel good after an apple, and it makes a fantastic noise when you bite into an apple.","startMs":255780,"endMs":261640},{"speaker":"Neil","text":"That noise is called a crunch.","startMs":261640,"endMs":263580},{"speaker":"Neil","text":"it''s a very nice sound.","startMs":264640,"endMs":267770},{"speaker":"Becca","text":"And so, we can describe apples as being crunchy.","startMs":267770,"endMs":270790},{"speaker":"Becca","text":"That''s the adjective.","startMs":270790,"endMs":271840},{"speaker":"Becca","text":"It''s time to recap the vocabulary that we''ve learned.","startMs":280640,"endMs":283480},{"speaker":"Becca","text":"And we''ll start with sour.","startMs":283480,"endMs":284900},{"speaker":"Becca","text":"And that is the taste, for example, in lemon or in vinegar – it''s not very sweet.","startMs":285260,"endMs":291520},{"speaker":"Becca","text":"Citrus fruits, for example, like grapefruit, oranges, limes – they are very sour.","startMs":291660,"endMs":297800},{"speaker":"Neil","text":"We used the word ripe.","startMs":298820,"endMs":300440},{"speaker":"Neil","text":"Ripe describes fruit which is ready to eat.","startMs":300680,"endMs":303900},{"speaker":"Becca","text":"We also had juicy, and that''s an adjective to describe something that has juice or liquid.","startMs":304220,"endMs":310110},{"speaker":"Becca","text":"So, for example, a juicy fruit like a strawberry – when you bite into it, juice will come out of it.","startMs":310110,"endMs":316980},{"speaker":"Neil","text":"We also heard about dried fruit.","startMs":317960,"endMs":320340},{"speaker":"Neil","text":"Dried fruit has had all of the juice taken out of it, sometimes by the sun.","startMs":320480,"endMs":326860},{"speaker":"Neil","text":"So, for example, raisins are dried fruit.","startMs":326860,"endMs":329920},{"speaker":"Becca","text":"That''s it for this week''s episode of Real Easy English.","startMs":330640,"endMs":333970},{"speaker":"Becca","text":"You can find a free worksheet on our website to test what you''ve learned from this episode.","startMs":333970,"endMs":338880},{"speaker":"Neil","text":"And we''ll be back next week with another episode of Real Easy English.","startMs":342140,"endMs":345920},{"speaker":"Becca","text":"Bye!","startMs":347580,"endMs":347840}]'::jsonb,
  'Understand and discuss talking about fruit using BBC natural English. You''ll pick up useful words like berries, grapes, sour. Listen to Becca & Neil talk it through in natural English.',
  '["Hello and welcome to Real Easy English, where we have easy conversations to help you with your listening skills and learn new vocabulary.","If you''d like to see a video version of this podcast, you can find it on our website at bbclearningenglish.","Yes, I saw you eating your banana, and I thought, I''m going to eat a banana."]'::jsonb,
  '[{"word":"berries","phonetic":"","pos":"Noun","translation":"rezavor mevalar","definition":"small soft fruits such as strawberries or blueberries","example":"Ooh, besides bananas, I really love berries."},{"word":"grapes","phonetic":"","pos":"Noun","translation":"uzum","definition":"small round fruits that grow in bunches","example":"And I like green apples and red grapes."},{"word":"sour","phonetic":"","pos":"Adjective","translation":"nordon","definition":"having a sharp taste like lemon","example":"Oranges can be a little sweet, but they''re actually more sour, aren''t they?"},{"word":"sharp","phonetic":"","pos":"Adjective","translation":"o‘tkir nordon","definition":"strong and sour in taste","example":"Yeah. Sour or sharp."},{"word":"citrus fruit","phonetic":"","pos":"Noun phrase","translation":"sitrus mevalar","definition":"fruits such as oranges, lemons, and limes","example":"These are called citrus fruit."},{"word":"juicy","phonetic":"","pos":"Adjective","translation":"sersuv","definition":"containing a lot of juice","example":"It''s at its sweetest usually, probably quite juicy."}]'::jsonb,
  '[{"type":"mc","question":"What does \"berries\" mean in this lesson?","options":["small soft fruits such as strawberries or blueberries","small round fruits that grow in bunches","having a sharp taste like lemon","strong and sour in taste"],"correct":0,"explanation":"\"berries\" means: small soft fruits such as strawberries or blueberries"},{"type":"mc","question":"What does \"grapes\" mean in this lesson?","options":["small soft fruits such as strawberries or blueberries","having a sharp taste like lemon","strong and sour in taste","small round fruits that grow in bunches"],"correct":3,"explanation":"\"grapes\" means: small round fruits that grow in bunches"},{"type":"mc","question":"What does \"sour\" mean in this lesson?","options":["small round fruits that grow in bunches","strong and sour in taste","having a sharp taste like lemon","small soft fruits such as strawberries or blueberries"],"correct":2,"explanation":"\"sour\" means: having a sharp taste like lemon"},{"type":"mc","question":"What does \"sharp\" mean in this lesson?","options":["having a sharp taste like lemon","strong and sour in taste","small soft fruits such as strawberries or blueberries","small round fruits that grow in bunches"],"correct":1,"explanation":"\"sharp\" means: strong and sour in taste"}]'::jsonb,
  'Understand and discuss talking about fruit using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

