insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_poetry_power', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260604_6_minute_english_the_power_of_poetry_download.mp3', 365,
  '[{"speaker":"Neil","text":"Hello, this is 6 Minute English from BBC Learning English.","startMs":7840,"endMs":11100},{"speaker":"Pippa","text":"In this episode we''re discussing poetry.","startMs":13260,"endMs":15740},{"speaker":"Pippa","text":"For some, poetry is what you study at school, then forget, while for others it becomes an important part of their life.","startMs":16240,"endMs":23780},{"speaker":"Pippa","text":"Have you ever read or written any poetry, Neil?","startMs":24180,"endMs":26980},{"speaker":"Neil","text":"Well, I haven''t written any poetry since I was at school.","startMs":27360,"endMs":31120},{"speaker":"Neil","text":"I would love to read more poetry, but I just don''t get it, really.","startMs":31260,"endMs":36380},{"speaker":"Neil","text":"I find it difficult to understand.","startMs":36420,"endMs":38260},{"speaker":"Pippa","text":"A good place to hear poetry is an open mic night, a live event where anyone is allowed to stand up on stage to sing or recite poems.","startMs":38540,"endMs":47440},{"speaker":"Pippa","text":"Here, BBC reporter Maria recites her open mic poem about a friend who suffered a stroke, for BBC World Service programme People Fixing the World.","startMs":48020,"endMs":56720},{"speaker":"Maria","text":"This first poem, I wrote it about a friend who I love dearly.","startMs":56940,"endMs":60060},{"speaker":"Maria","text":"You''re awake And trying to grasp who it is.","startMs":62720,"endMs":65260},{"speaker":"Maria","text":"I pull my mask past my lips and you study my face, Eyes wide.","startMs":65580,"endMs":69320},{"speaker":"Maria","text":"I''ve enough stuff to tell you, I say, Sinking into a chair.","startMs":70960,"endMs":74840},{"speaker":"Maria","text":"Sometimes if you go to an open mic night, people can really touch your soul with what they''re saying.","startMs":77880,"endMs":82780},{"speaker":"Maria","text":"And even if you''re having a bad day, life can feel so much better after going to an open mic night.","startMs":83400,"endMs":87580},{"speaker":"Neil","text":"For Maria, poetry has the power to heal emotions and touch your soul, meaning to affect you deeply on an emotional or spiritual level.","startMs":88240,"endMs":96920},{"speaker":"Pippa","text":"In this episode, we''ll hear more about the positive power of poetry and, as usual, we''ll learn some useful new words and phrases.","startMs":97280,"endMs":105500},{"speaker":"Pippa","text":"And remember, you''ll find all the vocabulary, plus a quiz and worksheet on our website, bbclearningenglish.","startMs":105860,"endMs":110800},{"speaker":"Neil","text":"But first, I have a question for you, Pippa.","startMs":113060,"endMs":115860},{"speaker":"Neil","text":"Just now you used the phrase the positive power of poetry, repeating the same initial ''p'' sound across a string of words.","startMs":116060,"endMs":124880},{"speaker":"Neil","text":"Doing this is a common feature of poetry, but what''s it called?","startMs":125520,"endMs":129240},{"speaker":"Neil","text":"Is it: a) assonance, b) alliteration, or c) simile?","startMs":129580,"endMs":134940},{"speaker":"Pippa","text":"Finally, my English degree might come in handy!","startMs":136080,"endMs":138540},{"speaker":"Pippa","text":"And I''m going to say b) alliteration.","startMs":138580,"endMs":140640},{"speaker":"Neil","text":"Well, we''ll find out at the end, and I hope you don''t get embarrassed, Pippa!","startMs":141100,"endMs":144600},{"speaker":"Neil","text":"Now, poetry helped Maria overcome sadness, but could its power to heal work in other areas too?","startMs":145760,"endMs":152600},{"speaker":"Neil","text":"Hot Poets is a group helping people understand the science behind global issues like climate change.","startMs":153220,"endMs":159220},{"speaker":"Neil","text":"They go to meetings like the UN Climate Conference and listen to scientific papers being presented.","startMs":159520,"endMs":164660},{"speaker":"Neil","text":"Then they write a poem about it all and perform that back to the audience.","startMs":164840,"endMs":169240},{"speaker":"Neil","text":"Here''s Hot Poet Liv Torc, reciting her poem to BBC World Service''s People Fixing the World.","startMs":169580,"endMs":175620},{"speaker":"Liv Torc","text":"It starts with an adventure at sea, A big blue murder mystery, where the killer is not the whale But an epic humanity fail Of overfishing and polluting at unimaginable scale.","startMs":176200,"endMs":188660},{"speaker":"Pippa","text":"Liv''s poem is based on a study into biodiversity.","startMs":192020,"endMs":195000},{"speaker":"Pippa","text":"It''s a complex research project that many find hard to understand.","startMs":195600,"endMs":199120},{"speaker":"Pippa","text":"Here, Liv discusses this with Myra Anubi for BBC World Service programme People Fixing the World:","startMs":199780,"endMs":205380},{"speaker":"Myra Anubi","text":"And Liv, I mean, so what you''ve identified is that there is an issue around the communication of science.","startMs":206140,"endMs":212520},{"speaker":"Liv Torc","text":"Yes, a lot of this jargon is really hard to understand, or a lot of the science is quite impenetrable to normal people, so it''s instantly a turn-off.","startMs":212960,"endMs":221000},{"speaker":"Neil","text":"Science uses lots of jargon – specialist or technical vocabulary which is quite different from everyday language.","startMs":221300,"endMs":227960},{"speaker":"Neil","text":"For example, a scientist might use the word precipitation, while in everyday English we would say rain.","startMs":228440,"endMs":234880},{"speaker":"Pippa","text":"Jargon can make scientific papers impenetrable, an adjective meaning impossible to understand.","startMs":235640,"endMs":241680},{"speaker":"Pippa","text":"And worse, it makes science a turn-off – something that people dislike or find uninteresting.","startMs":242380,"endMs":247320},{"speaker":"Neil","text":"Hot Poets try to change all of that by making complex environmental ideas easy to understand through poetry.","startMs":247880,"endMs":254460},{"speaker":"Neil","text":"And it works, says Kat Bruce, the environmental scientist whose study Liv based her poem on, talking here with Myra Anubi for BBC World Service''s People Fixing the World.","startMs":254760,"endMs":265580},{"speaker":"Myra Anubi","text":"What did it mean for you, Kat, hearing the poem, having actually experienced everything she''s saying?","startMs":265860,"endMs":271180},{"speaker":"Kat Bruce","text":"It still gives me goosebumps when I hear it now.","startMs":271680,"endMs":274600},{"speaker":"Kat Bruce","text":"I think it''s everything that I wish I could say and put into words myself.","startMs":274980,"endMs":281260},{"speaker":"Kat Bruce","text":"I feel like Liv just, you know, has done that.","startMs":281560,"endMs":284120},{"speaker":"Pippa","text":"Liv''s poem gave Kat goosebumps, meaning she was so emotionally affected that the hairs on her skin stood up, making tiny bumps.","startMs":285260,"endMs":293240},{"speaker":"Pippa","text":"Maybe poetry can''t fix everything, but for Kat, it''s making an impact for good.","startMs":293660,"endMs":298000},{"speaker":"Pippa","text":"Now, what was the answer to your question, Neil?","startMs":298460,"endMs":300560},{"speaker":"Neil","text":"Well, you seemed very clear, Pippa, that when you use a string of words beginning with the same sound, it''s called alliteration...","startMs":300900,"endMs":309740},{"speaker":"Neil","text":"and you''re absolutely right.","startMs":310760,"endMs":312200},{"speaker":"Pippa","text":"Phew!","startMs":312200,"endMs":314620},{"speaker":"Neil","text":"Let''s recap the vocabulary we''ve learned, starting with open mic night, a live event where anyone is allowed to perform poems or music on stage.","startMs":314620,"endMs":323300},{"speaker":"Pippa","text":"If something touches your soul, it affects you deeply on an emotional or spiritual level.","startMs":323660,"endMs":329180},{"speaker":"Neil","text":"Jargon means special words and phrases that are used in a particular profession or subject.","startMs":329520,"endMs":334400},{"speaker":"Pippa","text":"The adjective impenetrable means impossible to understand.","startMs":334700,"endMs":338260},{"speaker":"Neil","text":"A turn-off is something that people dislike or find uninteresting.","startMs":338540,"endMs":342440},{"speaker":"Pippa","text":"And finally, if you get goosebumps, the hairs on your skin stand up because you''re cold, emotionally affected, or afraid.","startMs":342740,"endMs":350740},{"speaker":"Pippa","text":"Once again, our six minutes are up, but remember, you''ll find lots more episodes as well as a quiz and worksheet for this one on our website, bbclearningenglish.","startMs":351220,"endMs":359680},{"speaker":"Pippa","text":"But for now, it''s goodbye.","startMs":363220,"endMs":364460},{"speaker":"Neil","text":"Goodbye!","startMs":364640,"endMs":364920}]'::jsonb,
  'Understand and discuss the power of poetry using BBC natural English. You''ll pick up useful words like open mic night, recite, touch your soul. Listen to Neil & Pippa talk it through in natural English.',
  '["Hello, this is 6 Minute English from BBC Learning English.","For some, poetry is what you study at school, then forget, while for others it becomes an important part of their life.","Well, I haven''t written any poetry since I was at school."]'::jsonb,
  '[{"word":"open mic night","phonetic":"","pos":"Noun phrase","translation":"ochiq sahna kechasi","definition":"a live event where anyone can perform","example":"A good place to hear poetry is an open mic night, a live event where anyone is allowed to stand up on stage to sing or recite poems."},{"word":"recite","phonetic":"","pos":"Verb","translation":"yoddan aytmoq","definition":"to say a poem or piece of writing aloud","example":"A good place to hear poetry is an open mic night, a live event where anyone is allowed to stand up on stage to sing or recite poems."},{"word":"touch your soul","phonetic":"","pos":"Phrase","translation":"qalbga ta’sir qilmoq","definition":"to affect you deeply emotionally","example":"Sometimes if you go to an open mic night, people can really touch your soul with what they''re saying."},{"word":"alliteration","phonetic":"","pos":"Noun","translation":"alliteratsiya","definition":"repetition of the same first sound in nearby words","example":"Is it: a) assonance, b) alliteration, or c) simile?"},{"word":"overcome","phonetic":"","pos":"Verb","translation":"yengib o‘tmoq","definition":"to successfully deal with a problem or feeling","example":"Now, poetry helped Maria overcome sadness, but could its power to heal work in other areas too?"},{"word":"heal","phonetic":"","pos":"Verb","translation":"davolamoq","definition":"to become healthy or less painful again","example":"For Maria, poetry has the power to heal emotions and touch your soul, meaning to affect you deeply on an emotional or spiritual level."}]'::jsonb,
  '[{"type":"mc","question":"What does \"open mic night\" mean in this lesson?","options":["a live event where anyone can perform","to say a poem or piece of writing aloud","to affect you deeply emotionally","repetition of the same first sound in nearby words"],"correct":0,"explanation":"\"open mic night\" means: a live event where anyone can perform"},{"type":"mc","question":"What does \"recite\" mean in this lesson?","options":["a live event where anyone can perform","to affect you deeply emotionally","repetition of the same first sound in nearby words","to say a poem or piece of writing aloud"],"correct":3,"explanation":"\"recite\" means: to say a poem or piece of writing aloud"},{"type":"mc","question":"What does \"touch your soul\" mean in this lesson?","options":["to say a poem or piece of writing aloud","repetition of the same first sound in nearby words","to affect you deeply emotionally","a live event where anyone can perform"],"correct":2,"explanation":"\"touch your soul\" means: to affect you deeply emotionally"},{"type":"mc","question":"What does \"alliteration\" mean in this lesson?","options":["to affect you deeply emotionally","repetition of the same first sound in nearby words","a live event where anyone can perform","to say a poem or piece of writing aloud"],"correct":1,"explanation":"\"alliteration\" means: repetition of the same first sound in nearby words"}]'::jsonb,
  'Understand and discuss the power of poetry using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

