insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_living_with_debt', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260528_6_minute_english_living_with_debt_download.mp3', 367,
  '[{"speaker":"Neil","text":"Hello, this is 6 Minute English from BBC Learning English.","startMs":8020,"endMs":11540},{"speaker":"Pippa","text":"Are you good at saving money, Neil?","startMs":13860,"endMs":15880},{"speaker":"Pippa","text":"Or do you like to spend it?","startMs":16200,"endMs":17560},{"speaker":"Neil","text":"Well, actually, a bit of both.","startMs":17840,"endMs":20400},{"speaker":"Neil","text":"I like to spend money on nice things, but I also try to save, mainly because I''ve got children.","startMs":20860,"endMs":27360},{"speaker":"Pippa","text":"I like to save money, or I try to, for the future.","startMs":30380,"endMs":33720},{"speaker":"Pippa","text":"But I also do spend it.","startMs":34740,"endMs":36800},{"speaker":"Pippa","text":"I don''t count every penny that I spend and save every single penny that I earn.","startMs":36880,"endMs":41580},{"speaker":"Neil","text":"Well, whether you''re a saver or a spender, being in debt is common in the UK.","startMs":42560,"endMs":48180},{"speaker":"Neil","text":"Debt refers to money a person has borrowed to buy something and which they have to pay back, usually to a bank, a credit card company, or another person.","startMs":48540,"endMs":57760},{"speaker":"Pippa","text":"Many people avoid talking about debt, but it affects us all.","startMs":58580,"endMs":63080},{"speaker":"Pippa","text":"In 2025, over 1000 people contacted the UK Citizens Advice Bureau every single day of the year for help with their debt.","startMs":63300,"endMs":71880},{"speaker":"Pippa","text":"And when debt gets out of control, it causes stress and worry.","startMs":72520,"endMs":76120},{"speaker":"Pippa","text":"BBC Radio 4 programme Thinking Allowed interviewed one young man, Jason, about his debt.","startMs":76600,"endMs":82480},{"speaker":"Jason","text":"Whatever jobs there are aren''t enough to provide for a family.","startMs":83160,"endMs":85340},{"speaker":"Jason","text":"Sometimes you need to take out loans.","startMs":85540,"endMs":86900},{"speaker":"Jason","text":"I''ve done it a few times, but you can''t ever pay it back.","startMs":87060,"endMs":89640},{"speaker":"Jason","text":"You can''t see a way out, other than winning the lottery or something.","startMs":89920,"endMs":92400},{"speaker":"Jason","text":"I''d like to think I could clear them all one day, even if it means, like, five years paying them off.","startMs":92780,"endMs":97360},{"speaker":"Neil","text":"Jason uses three phrases, pay back, pay off, and clear debt, all of which mean the same thing – to give back the money you''ve borrowed.","startMs":97780,"endMs":107920},{"speaker":"Pippa","text":"In this episode, we''ll hear more about living with debt by learning some useful new words and phrases.","startMs":108540,"endMs":114540},{"speaker":"Pippa","text":"And remember, you''ll find all the vocabulary used, plus a quiz and worksheet, on our website, bbclearningenglish.","startMs":115020,"endMs":122620},{"speaker":"Neil","text":"But first, I have a question for you, Pippa.","startMs":122840,"endMs":125360},{"speaker":"Neil","text":"According to debt support group The Money Charity, roughly how much is the average British adult in debt through credit cards, overdrafts and personal loans?","startMs":125740,"endMs":137340},{"speaker":"Neil","text":"Is it: a) £2,200, b) £4,200, or c) £6,200?","startMs":137860,"endMs":144120},{"speaker":"Pippa","text":"Hmm. I''m not sure. I''ll say £2,200.","startMs":146480,"endMs":148480},{"speaker":"Neil","text":"Well, we will find out the answer later in the programme.","startMs":150980,"endMs":153780},{"speaker":"Neil","text":"Jason''s story features in a new book by sociologist Ryan Davey.","startMs":154240,"endMs":158800},{"speaker":"Neil","text":"Ryan spent months living in a low-income housing estate, which he gave the fictional name Woldham.","startMs":159020,"endMs":164540},{"speaker":"Neil","text":"He talked with residents and listened to their money worries.","startMs":165600,"endMs":168320},{"speaker":"Neil","text":"Here, Ryan explains more to BBC Radio 4''s Thinking Allowed:","startMs":168760,"endMs":172560},{"speaker":"Ryan Davey","text":"My approach was to let people know that I was interested in learning about their lives and how they were making ends meet, so I did some interviews with residents, and I paid attention to where debt came up in everyday conversations.","startMs":173360,"endMs":184900},{"speaker":"Ryan Davey","text":"For many people in Woldham, Jason included, debt was an ordinary feature of daily life.","startMs":185160,"endMs":191660},{"speaker":"Ryan Davey","text":"And beyond that, being in arrears – so, being behind with one or more monthly payment commitments – was part of daily life.","startMs":191800,"endMs":198240},{"speaker":"Pippa","text":"The people of Woldham were making ends meet.","startMs":198580,"endMs":201720},{"speaker":"Pippa","text":"To make ends meet means having just enough money to pay for basic living expenses like food, bills and rent.","startMs":202000,"endMs":209020},{"speaker":"Neil","text":"Ryan found that many residents were in arrears, a phrase meaning to still owe money that should have already been repaid.","startMs":209580,"endMs":216820},{"speaker":"Neil","text":"For most residents, debt was a normal part of daily life.","startMs":217400,"endMs":220940},{"speaker":"Pippa","text":"With a regular income, debt can be managed, but for those who are unemployed or on low incomes, it can cause serious distress.","startMs":221780,"endMs":230320},{"speaker":"Pippa","text":"Here, Ryan discusses how the residents he met felt about their debt with BBC Radio 4''s Thinking Allowed:","startMs":230820,"endMs":236540},{"speaker":"Ryan Davey","text":"Jason actually fluctuated between wanting to clear all of his debts on the one hand, and on the other what he described as living on the never-never and actually questioning the supposed moral obligation to pay his debts.","startMs":237400,"endMs":251860},{"speaker":"Ryan Davey","text":"Over the months that I knew him, the financial strain on him and his partner increased.","startMs":252240,"endMs":258440},{"speaker":"Ryan Davey","text":"They missed some of their bills.","startMs":259340,"endMs":260700},{"speaker":"Ryan Davey","text":"Their internet was disconnected.","startMs":260900,"endMs":262080},{"speaker":"Neil","text":"Jason was living on the never-never, an informal phrase for buying the things you need by making regular small payments over a long time.","startMs":262540,"endMs":271440},{"speaker":"Neil","text":"It''s called the never- never because it seems the debt will never be repaid.","startMs":271700,"endMs":275920},{"speaker":"Pippa","text":"Jason experienced financial strain – emotional stress caused by a lack of money to meet his basic needs or to repay his debt.","startMs":276260,"endMs":284820},{"speaker":"Pippa","text":"Debt is a serious issue.","startMs":285300,"endMs":286840},{"speaker":"Pippa","text":"It affects many people and there are support groups who can help if you need it.","startMs":287100,"endMs":291100},{"speaker":"Pippa","text":"Neil, what was the answer to your question?","startMs":292080,"endMs":294240},{"speaker":"Neil","text":"I asked what the average amount of debt a British adult has through credit cards, overdrafts and personal loans.","startMs":294540,"endMs":302320},{"speaker":"Pippa","text":"I said it was around £2,200.","startMs":302800,"endMs":304060},{"speaker":"Neil","text":"I''m afraid that''s not the right answer.","startMs":305760,"endMs":308200},{"speaker":"Neil","text":"In fact, it''s £4,232.","startMs":308560,"endMs":309620},{"speaker":"Neil","text":"Let''s recap the vocabulary we''ve learned, starting with debt – money a person has borrowed and needs to give back.","startMs":313320,"endMs":320040},{"speaker":"Pippa","text":"The phrases to pay back, to pay off, and to clear a debt all mean to give back money you have borrowed.","startMs":320440,"endMs":326740},{"speaker":"Neil","text":"If someone is making ends meet, they have just enough money to pay for basic living expenses.","startMs":327200,"endMs":333040},{"speaker":"Neil","text":"And if they are in arrears, they still owe money that should have been repaid already.","startMs":333040,"endMs":338100},{"speaker":"Pippa","text":"If you buy something on the never-never, you buy it by making small regular payments over a long period.","startMs":338500,"endMs":345060},{"speaker":"Neil","text":"And finally, financial strain is emotional stress caused by a lack of money to meet your basic needs.","startMs":345640,"endMs":351600},{"speaker":"Pippa","text":"Once again, our six minutes are up, but if you''d like to know how debt is spelled and all the other words from this episode, visit our website,","startMs":352040,"endMs":360540},{"speaker":"Neil","text":"But for now, it''s goodbye.","startMs":365620,"endMs":366880},{"speaker":"Pippa","text":"Bye!","startMs":366960,"endMs":367280}]'::jsonb,
  'Understand and discuss living with debt using BBC natural English. You''ll pick up useful words like debt, pay back, pay off. Listen to Neil & Pippa talk it through in natural English.',
  '["Hello, this is 6 Minute English from BBC Learning English.","I like to spend money on nice things, but I also try to save, mainly because I''ve got children.","I don''t count every penny that I spend and save every single penny that I earn."]'::jsonb,
  '[{"word":"debt","phonetic":"","pos":"Noun","translation":"qarz","definition":"money that has been borrowed and must be paid back","example":"Well, whether you''re a saver or a spender, being in debt is common in the UK."},{"word":"pay back","phonetic":"","pos":"Phrasal verb","translation":"qarzni qaytarmoq","definition":"to return borrowed money","example":"Debt refers to money a person has borrowed to buy something and which they have to pay back, usually to a bank, a credit card company, or another person."},{"word":"pay off","phonetic":"","pos":"Phrasal verb","translation":"qarzni to‘lab tugatmoq","definition":"to finish paying all money owed","example":"Debt refers to money a person has borrowed to buy something and which they have to pay back, usually to a bank, a credit card company, or another person."},{"word":"clear debt","phonetic":"","pos":"Phrase","translation":"qarzni yopmoq","definition":"to remove debt by paying it","example":"I''d like to think I could clear them all one day, even if it means, like, five years paying them off."},{"word":"take out loans","phonetic":"","pos":"Phrase","translation":"kredit olmoq","definition":"to borrow money formally","example":"Sometimes you need to take out loans."},{"word":"way out","phonetic":"","pos":"Noun phrase","translation":"chiqish yo‘li","definition":"a solution or escape from a difficult situation","example":"You can''t see a way out, other than winning the lottery or something."}]'::jsonb,
  '[{"type":"mc","question":"What does \"debt\" mean in this lesson?","options":["money that has been borrowed and must be paid back","to return borrowed money","to finish paying all money owed","to remove debt by paying it"],"correct":0,"explanation":"\"debt\" means: money that has been borrowed and must be paid back"},{"type":"mc","question":"What does \"pay back\" mean in this lesson?","options":["money that has been borrowed and must be paid back","to finish paying all money owed","to remove debt by paying it","to return borrowed money"],"correct":3,"explanation":"\"pay back\" means: to return borrowed money"},{"type":"mc","question":"What does \"pay off\" mean in this lesson?","options":["to return borrowed money","to remove debt by paying it","to finish paying all money owed","money that has been borrowed and must be paid back"],"correct":2,"explanation":"\"pay off\" means: to finish paying all money owed"},{"type":"mc","question":"What does \"clear debt\" mean in this lesson?","options":["to finish paying all money owed","to remove debt by paying it","money that has been borrowed and must be paid back","to return borrowed money"],"correct":1,"explanation":"\"clear debt\" means: to remove debt by paying it"}]'::jsonb,
  'Understand and discuss living with debt using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

