insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_quiet_cities', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260521_6_minute_english_making_cities_feel_quieter_download.mp3', 373,
  '[{"speaker":"Neil","text":"This is 6 Minute English from BBC Learning English.","startMs":8500,"endMs":11380},{"speaker":"Georgie","text":"Neil, I''m going to play you two sound recordings, and I want you to tell me how you feel when you hear them.","startMs":13500,"endMs":19160},{"speaker":"Neil","text":"OK.","startMs":19160,"endMs":19560},{"speaker":"Georgie","text":"First this… And now this.","startMs":20000,"endMs":27540},{"speaker":"Neil","text":"Oh, well, that first clip made me feel really relaxed.","startMs":31880,"endMs":35640},{"speaker":"Neil","text":"But the second one – oh, it''s horrible!","startMs":35940,"endMs":38180},{"speaker":"Neil","text":"I felt quite stressed out actually.","startMs":38320,"endMs":40140},{"speaker":"Georgie","text":"Well, this little experiment shows how much we are affected by the noise around us.","startMs":41180,"endMs":45620},{"speaker":"Georgie","text":"And that''s a problem if you''re one of the four billion people around the world who live in cities.","startMs":45820,"endMs":50220},{"speaker":"Neil","text":"Yes, whether it''s the rattle of train tracks, honking car horns, or the roar of aeroplanes overhead, modern cities are full of noise and this can have serious effects.","startMs":50640,"endMs":61280},{"speaker":"Neil","text":"The World Health Organisation reports that by 2050, around 2.","startMs":61500,"endMs":65360},{"speaker":"Neil","text":"5 billion people will experience hearing loss, and exposure to loud noise has been linked to stress and anxiety.","startMs":66040,"endMs":72480},{"speaker":"Georgie","text":"In this episode, we''ll be hearing about ways to make our cities quieter, more relaxing places, using some useful new words and phrases.","startMs":73040,"endMs":80900},{"speaker":"Georgie","text":"And remember, you''ll find all the vocabulary along with a quiz and worksheet on our website,","startMs":81140,"endMs":86360},{"speaker":"Neil","text":"But now I have a question for you, Georgie.","startMs":88600,"endMs":91120},{"speaker":"Neil","text":"Sound is measured in units called decibels.","startMs":91540,"endMs":94040},{"speaker":"Neil","text":"But how many decibels would it be if I whispered?","startMs":94220,"endMs":97800},{"speaker":"Neil","text":"A whisper is speaking like this.","startMs":98480,"endMs":100220},{"speaker":"Neil","text":"Is it: a) 3 decibels, b) 13 decibels, or c) 30 decibels?","startMs":100680,"endMs":106860},{"speaker":"Georgie","text":"Oh, that''s really hard.","startMs":107080,"endMs":108260},{"speaker":"Georgie","text":"I''ll go for b) 13 decibels.","startMs":108820,"endMs":111080},{"speaker":"Neil","text":"Well, we''ll find out the answer at the end of the programme.","startMs":111300,"endMs":114540},{"speaker":"Neil","text":"Let''s start in one of the noisiest cities in the world – Mumbai in India, where daytime noise levels regularly hit 80 decibels, which is over 20 decibels higher than World Health Organisation recommendations.","startMs":115300,"endMs":128800},{"speaker":"Neil","text":"Listen to Mumbai native Chhavi Sachdev share her experiences of living in this noisy city with BBC World Service programme People Fixing the World.","startMs":129600,"endMs":138700},{"speaker":"Chhavi Sachdev","text":"I mean, India in general is just really loud.","startMs":139140,"endMs":141990},{"speaker":"Chhavi Sachdev","text":"We are a loud people.","startMs":141990,"endMs":143120},{"speaker":"Chhavi Sachdev","text":"We dress loud, we talk loud, we celebrate loud, we watch movies loud.","startMs":143420,"endMs":147300},{"speaker":"Chhavi Sachdev","text":"When people ask me what I miss about living abroad, I tell them it''s the quiet, because after 12 years of living in the US and Europe, when I got back, I realised I couldn''t handle it anymore.","startMs":147580,"endMs":157570},{"speaker":"Chhavi Sachdev","text":"I''d gotten used to lower levels of noise.","startMs":157570,"endMs":159880},{"speaker":"Georgie","text":"Chhavi says, \"Indians talk loud, celebrate loud and dress loud.\"","startMs":160660,"endMs":164360},{"speaker":"Georgie","text":"To dress loud means to wear clothes with bright colours and large, bold patterns.","startMs":164580,"endMs":168900},{"speaker":"Neil","text":"When Chhavi returned to India after living overseas, she says she couldn''t handle the noise.","startMs":169240,"endMs":174340},{"speaker":"Neil","text":"If you can''t handle something, you find it difficult to deal or cope with.","startMs":174780,"endMs":178880},{"speaker":"Georgie","text":"So, what can be done to tackle noise in cities like Mumbai?","startMs":179180,"endMs":182520},{"speaker":"Georgie","text":"One interesting approach involves using sound itself to make things feel quieter.","startMs":182920,"endMs":187580},{"speaker":"Georgie","text":"Soundscaping is the idea of adding certain sounds to busy public spaces so that they sound and feel more relaxing.","startMs":188040,"endMs":194800},{"speaker":"Neil","text":"Sound artist Charles Montambault lives near the Parc des Madelinots, a busy city park in Montreal, Canada.","startMs":195480,"endMs":202040},{"speaker":"Neil","text":"Charles was inspired to recreate the ocean sounds he heard on holiday in the Magdalen Islands in his city park back home.","startMs":202600,"endMs":209680},{"speaker":"Neil","text":"On BBC World Service programme People Fixing the World, he tells reporter Natasha Fernandes that these sounds included ocean waves and some unusual-sounding sand.","startMs":210220,"endMs":220120},{"speaker":"Charles Montambault","text":"The sand on the Magdalen Islands can sing.","startMs":220620,"endMs":223150},{"speaker":"Charles Montambault","text":"When you walk into the sand firmly, the sand makes some squeaky sounds, so that''s one sound that is kind of funny, kind of special.","startMs":223150,"endMs":231720},{"speaker":"Natasha Fernandes","text":"Inside the small park, surrounded by busy roads, Charles and his team set up an immersive sound art installation in the form of speakers planted in flower beds.","startMs":232160,"endMs":241300},{"speaker":"Charles Montambault","text":"So, the art installation was really to make this park a little quieter by adding some quiet noises.","startMs":241600,"endMs":248260},{"speaker":"Charles Montambault","text":"So, it''s counterintuitive, but you can make a park less noisy by adding some calmer sounds.","startMs":249640,"endMs":257840},{"speaker":"Georgie","text":"The sand on the Magdalen Islands is squeaky – it makes a high-pitched sound called a squeak when stepped on.","startMs":258580,"endMs":264760},{"speaker":"Georgie","text":"Charles played recordings of this sand, ocean waves and other relaxing sounds through speakers hidden in the park.","startMs":265060,"endMs":271360},{"speaker":"Georgie","text":"He created an art installation – a work of art designed to give people an interactive experience.","startMs":271720,"endMs":277760},{"speaker":"Neil","text":"By adding more relaxing sounds, Charles'' art installation actually made the park feel quieter.","startMs":278100,"endMs":283460},{"speaker":"Neil","text":"It''s an example of something that''s counterintuitive, meaning it happens differently from how you would expect.","startMs":283900,"endMs":290060},{"speaker":"Georgie","text":"And similar soundscapes are now helping city dwellers relax in other cities too, including Tokyo and Barcelona.","startMs":291800,"endMs":298280},{"speaker":"Georgie","text":"Now Neil, you asked me a question about a very quiet sound – a whisper.","startMs":298740,"endMs":303560},{"speaker":"Georgie","text":"So, are you going to reveal the correct answer?","startMs":303560,"endMs":306300},{"speaker":"Neil","text":"I asked you how loud a whisper is.","startMs":307000,"endMs":310300},{"speaker":"Georgie","text":"Yes, and I said 13 decibels.","startMs":310520,"endMs":313080},{"speaker":"Neil","text":"Well, 13 is an unlucky number and you are wrong.","startMs":313220,"endMs":316000},{"speaker":"Georgie","text":"Ah!","startMs":316060,"endMs":316520},{"speaker":"Neil","text":"Let''s recap the vocabulary we''ve learned, starting with decibel – the unit for measuring sound.","startMs":320440,"endMs":325400},{"speaker":"Georgie","text":"Someone who dresses loud likes to wear clothes with bright colours and bold designs.","startMs":325820,"endMs":330220},{"speaker":"Neil","text":"If you can''t handle something, you find it difficult to deal with.","startMs":330660,"endMs":334180},{"speaker":"Georgie","text":"An art installation is an artwork designed to create an interactive experience in a certain space.","startMs":334360,"endMs":339920},{"speaker":"Neil","text":"The adjective squeaky describes things which make a high-pitched sound like a mouse.","startMs":340260,"endMs":345800},{"speaker":"Georgie","text":"And finally, if you call something counterintuitive, you mean it happens differently from how you would expect.","startMs":347440,"endMs":352900},{"speaker":"Georgie","text":"Once again, our six minutes are up, but if you''d like to hear more about this and many other trending topics, you''ll find more episodes and learning activities on our website, bbclearningenglish.","startMs":353300,"endMs":364220},{"speaker":"Georgie","text":"But for now, it''s goodbye.","startMs":365460,"endMs":366760},{"speaker":"Neil","text":"Goodbye...!","startMs":367160,"endMs":367540}]'::jsonb,
  'Understand and discuss making cities feel quieter using BBC natural English. You''ll pick up useful words like quieter, noise pollution, soundscape. Listen to Neil & Beth talk it through in natural English.',
  '["Neil, I''m going to play you two sound recordings, and I want you to tell me how you feel when you hear them.","Well, this little experiment shows how much we are affected by the noise around us.","And that''s a problem if you''re one of the four billion people around the world who live in cities."]'::jsonb,
  '[{"word":"quieter","phonetic":"","pos":"Adjective","translation":"tinchroq","definition":"having less noise","example":"In this episode, we''ll be hearing about ways to make our cities quieter, more relaxing places, using some useful new words and phrases."},{"word":"noise pollution","phonetic":"","pos":"Noun phrase","translation":"shovqin ifloslanishi","definition":"harmful or annoying levels of noise","example":"Well, this little experiment shows how much we are affected by the noise around us."},{"word":"soundscape","phonetic":"","pos":"Noun","translation":"tovush muhiti","definition":"the mixture of sounds in a place","example":"And similar soundscapes are now helping city dwellers relax in other cities too, including Tokyo and Barcelona."},{"word":"traffic","phonetic":"","pos":"Noun","translation":"yo‘l harakati","definition":"vehicles moving on roads","example":"Neil, I''m going to play you two sound recordings, and I want you to tell me how you feel when you hear them."},{"word":"urban","phonetic":"","pos":"Adjective","translation":"shahar bilan bog‘liq","definition":"connected with a city","example":"Neil, I''m going to play you two sound recordings, and I want you to tell me how you feel when you hear them."},{"word":"reduce","phonetic":"","pos":"Verb","translation":"kamaytirmoq","definition":"to make something smaller or less","example":"Neil, I''m going to play you two sound recordings, and I want you to tell me how you feel when you hear them."}]'::jsonb,
  '[{"type":"mc","question":"What does \"quieter\" mean in this lesson?","options":["having less noise","harmful or annoying levels of noise","the mixture of sounds in a place","vehicles moving on roads"],"correct":0,"explanation":"\"quieter\" means: having less noise"},{"type":"mc","question":"What does \"noise pollution\" mean in this lesson?","options":["having less noise","the mixture of sounds in a place","vehicles moving on roads","harmful or annoying levels of noise"],"correct":3,"explanation":"\"noise pollution\" means: harmful or annoying levels of noise"},{"type":"mc","question":"What does \"soundscape\" mean in this lesson?","options":["harmful or annoying levels of noise","vehicles moving on roads","the mixture of sounds in a place","having less noise"],"correct":2,"explanation":"\"soundscape\" means: the mixture of sounds in a place"},{"type":"mc","question":"What does \"traffic\" mean in this lesson?","options":["the mixture of sounds in a place","vehicles moving on roads","having less noise","harmful or annoying levels of noise"],"correct":1,"explanation":"\"traffic\" means: vehicles moving on roads"}]'::jsonb,
  'Understand and discuss making cities feel quieter using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

