insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_reading_brain', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260514_6_minute_english_how_reading_shapes_your_brain_download.mp3', 365,
  '[{"speaker":"Becca","text":"Welcome to 6 Minute English from BBC Learning English.","startMs":9280,"endMs":12760},{"speaker":"Georgie","text":"Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish.","startMs":15000,"endMs":21740},{"speaker":"Georgie","text":"Now, Becca, do you read a lot?","startMs":23200,"endMs":24900},{"speaker":"Becca","text":"Hmm, I don''t read often.","startMs":25040,"endMs":27200},{"speaker":"Becca","text":"I just feel like I don''t have the time, Georgie.","startMs":27360,"endMs":29580},{"speaker":"Georgie","text":"I would love to read more, but I don''t read very much at the moment.","startMs":30860,"endMs":34870},{"speaker":"Georgie","text":"I read mostly before bed because I feel like it helps me relax and go to sleep.","startMs":34870,"endMs":39760},{"speaker":"Georgie","text":"And today we''re talking all about reading.","startMs":40900,"endMs":43140},{"speaker":"Georgie","text":"We''ll be hearing from some experts about how reading can change our brains, and as usual we''ll be learning some useful new words and phrases.","startMs":43200,"endMs":50560},{"speaker":"Becca","text":"Let''s start with a quiz question.","startMs":51060,"endMs":52960},{"speaker":"Becca","text":"The longest novel in the world is widely thought to be by French author Marcel Proust, a book which, when translated into English, means Remembrance of Things Past.","startMs":53240,"endMs":64020},{"speaker":"Becca","text":"But how many words does the book contain?","startMs":64880,"endMs":66780},{"speaker":"Becca","text":"Is it: a) 130,000, b) 1.","startMs":67420,"endMs":71000},{"speaker":"Becca","text":"3 million, or c) 13 million?","startMs":72000,"endMs":74540},{"speaker":"Georgie","text":"The longest novel in the world.","startMs":75320,"endMs":77360},{"speaker":"Georgie","text":"I still think 13 million words sounds too many, so I''m going to go with b) 1.","startMs":77460,"endMs":82320},{"speaker":"Becca","text":"We''ll find out at the end of the programme.","startMs":84600,"endMs":86700},{"speaker":"Becca","text":"Now, we might think of reading as like speaking.","startMs":87080,"endMs":90060},{"speaker":"Becca","text":"We''re born with the potential to do it and then we learn.","startMs":90540,"endMs":93500},{"speaker":"Becca","text":"If something is natural, it''s something you were born with or that comes from nature.","startMs":94620,"endMs":99280},{"speaker":"Georgie","text":"But Maryanne Wolf, author of the book Reader Come Home, says that this isn''t true.","startMs":99560,"endMs":105140},{"speaker":"Maryanne Wolf","text":"We think of language as natural, and reading is written language so it must be natural.","startMs":105900,"endMs":112760},{"speaker":"Maryanne Wolf","text":"It isn''t natural at all.","startMs":114380,"endMs":116480},{"speaker":"Becca","text":"Scientific studies suggest that when we''re born, our brains already have the networks that allow our eyes to see and our vocal cords to produce sounds, but not with the pathways we need to read.","startMs":116760,"endMs":128900},{"speaker":"Georgie","text":"Let''s hear more from psychologist and neuroscientist Rebecca Gotlieb, speaking to the BBC World Service.","startMs":129260,"endMs":135100},{"speaker":"Rebecca Gotlieb","text":"From an evolutionary timescale, our brain hasn''t had enough time to develop a dedicated reading brain.","startMs":135560,"endMs":142140},{"speaker":"Rebecca Gotlieb","text":"And so, to build a reading brain network, we co-opt parts of the brain involved in vision and auditory processing, and language, and attention and affect.","startMs":142440,"endMs":153480},{"speaker":"Rebecca Gotlieb","text":"Reading is really a whole brain process.","startMs":154020,"endMs":156360},{"speaker":"Rebecca Gotlieb","text":"It involves activation in all four lobes of the cortex.","startMs":157020,"endMs":162020},{"speaker":"Rebecca Gotlieb","text":"The process of developing a reading brain alters everything, from brain activity to brain structure and brain connectivity.","startMs":162300,"endMs":172500},{"speaker":"Rebecca Gotlieb","text":"The power of deep reading is really fundamental to our humanity.","startMs":173040,"endMs":177420},{"speaker":"Rebecca Gotlieb","text":"When we read deeply, we change our brains and we change who we are.","startMs":177620,"endMs":182100},{"speaker":"Becca","text":"Rebecca says that our brains haven''t evolved to include a dedicated reading brain.","startMs":182300,"endMs":187380},{"speaker":"Becca","text":"Dedicated here means designed and used for one particular purpose.","startMs":187560,"endMs":191560},{"speaker":"Georgie","text":"So, because we don''t have a part of the brain designed specifically for reading, when we learn to read, we co-opt other parts of the brain.","startMs":191940,"endMs":199040},{"speaker":"Georgie","text":"Co-opt here means to include someone or something, often against their will.","startMs":199280,"endMs":203660},{"speaker":"Becca","text":"Learning to read means using lots of different parts of the brain that are designed for other things, and this changes our brain structure compared to someone who hasn''t learned to read.","startMs":204680,"endMs":214560},{"speaker":"Georgie","text":"And the language we read also shapes our brain.","startMs":215000,"endMs":217740},{"speaker":"Georgie","text":"Chinese characters, for example, use symbols instead of letters of the alphabet to represent words and ideas.","startMs":217920,"endMs":224540},{"speaker":"Becca","text":"Research suggests that learning to read these symbols activates different areas of the brain to reading an alphabet-based system.","startMs":225100,"endMs":232000},{"speaker":"Georgie","text":"Scientists studied a bilingual man who could read and speak Chinese and English.","startMs":232500,"endMs":237680},{"speaker":"Georgie","text":"The man suffered a stroke, which affected parts of his brain, including his ability to read Chinese.","startMs":238180,"endMs":244100},{"speaker":"Georgie","text":"But amazingly, he was still able to read English.","startMs":244500,"endMs":248040},{"speaker":"Becca","text":"Maryanne Wolf explains more to the BBC World Service.","startMs":248920,"endMs":251760},{"speaker":"Maryanne Wolf","text":"It''s a beautiful example of how the brain''s circuit reflects the requirements of Chinese, which inevitably means more visual memory and visual processing of those beautifully intricate symbols or characters.","startMs":252700,"endMs":272400},{"speaker":"Georgie","text":"Maryanne says that the brain''s circuit is shaped by learning to read Chinese.","startMs":273440,"endMs":276980},{"speaker":"Georgie","text":"A circuit is a system of connections.","startMs":277360,"endMs":279520},{"speaker":"Becca","text":"The visual qualities of Chinese symbols inevitably mean more visual areas of the brain are developed.","startMs":279820,"endMs":286260},{"speaker":"Becca","text":"Inevitably means in a way that cannot be stopped or avoided.","startMs":286800,"endMs":290060},{"speaker":"Georgie","text":"Maryanne describes the symbolic Chinese characters as beautifully intricate.","startMs":291540,"endMs":295380},{"speaker":"Georgie","text":"If something is intricate, it has lots of detail.","startMs":295780,"endMs":298420},{"speaker":"Becca","text":"And something which also has lots of detail, or certainly lots of words – I asked you, Georgie, how many words are in Marcel Proust''s Remembrance of Things Past.","startMs":298800,"endMs":309560},{"speaker":"Georgie","text":"I said 1.3 million.","startMs":309560,"endMs":312120},{"speaker":"Becca","text":"And you were correct!","startMs":312360,"endMs":314060},{"speaker":"Georgie","text":"Yay!","startMs":314060,"endMs":314540},{"speaker":"Becca","text":"The book also contains lots of very long sentences, including one with over 900 words.","startMs":314540,"endMs":321180},{"speaker":"Georgie","text":"One sentence with 900 words?","startMs":321240,"endMs":323180},{"speaker":"Georgie","text":"It''s time to recap the language we learned during this programme, starting with natural, which describes something you were born with or that comes from nature.","startMs":325180,"endMs":333220},{"speaker":"Becca","text":"Dedicated can describe something that is designed and used for one particular purpose.","startMs":333680,"endMs":338560},{"speaker":"Georgie","text":"If you co-opt someone or something, you involve them, sometimes against their will.","startMs":338820,"endMs":343380},{"speaker":"Becca","text":"A circuit is a system of connections – for example, in the brain.","startMs":343680,"endMs":347940},{"speaker":"Georgie","text":"Inevitably means in a way that cannot be stopped or avoided.","startMs":348140,"endMs":351360},{"speaker":"Becca","text":"And intricate describes something which has lots of detail.","startMs":351720,"endMs":355180},{"speaker":"Georgie","text":"That''s it for this episode of 6 Minute English.","startMs":355600,"endMs":358100},{"speaker":"Georgie","text":"Test what you''ve learnt with the worksheet on our website, bbclearningenglish.","startMs":358680,"endMs":360780},{"speaker":"Becca","text":"Thanks for joining us.","startMs":362460,"endMs":363980}]'::jsonb,
  'Understand and discuss how reading shapes your brain using BBC natural English. You''ll pick up useful words like shape, brain, empathy. Listen to Neil & Beth talk it through in natural English.',
  '["Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish.","I would love to read more, but I don''t read very much at the moment.","I read mostly before bed because I feel like it helps me relax and go to sleep."]'::jsonb,
  '[{"word":"shape","phonetic":"","pos":"Verb","translation":"shakllantirmoq","definition":"to influence how something develops","example":"And the language we read also shapes our brain."},{"word":"brain","phonetic":"","pos":"Noun","translation":"miya","definition":"the organ in your head used for thinking","example":"We''ll be hearing from some experts about how reading can change our brains, and as usual we''ll be learning some useful new words and phrases."},{"word":"empathy","phonetic":"","pos":"Noun","translation":"hamdardlik","definition":"the ability to understand other people’s feelings","example":"Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish."},{"word":"imagination","phonetic":"","pos":"Noun","translation":"tasavvur","definition":"the ability to create ideas or pictures in your mind","example":"Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish."},{"word":"concentration","phonetic":"","pos":"Noun","translation":"diqqatni jamlash","definition":"the ability to focus attention","example":"Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish."},{"word":"fiction","phonetic":"","pos":"Noun","translation":"badiiy adabiyot","definition":"stories about imaginary people and events","example":"Remember, you can find all this episode''s vocabulary along with a transcript and worksheet on our website, bbclearningenglish."}]'::jsonb,
  '[{"type":"mc","question":"What does \"shape\" mean in this lesson?","options":["to influence how something develops","the organ in your head used for thinking","the ability to understand other people’s feelings","the ability to create ideas or pictures in your mind"],"correct":0,"explanation":"\"shape\" means: to influence how something develops"},{"type":"mc","question":"What does \"brain\" mean in this lesson?","options":["to influence how something develops","the ability to understand other people’s feelings","the ability to create ideas or pictures in your mind","the organ in your head used for thinking"],"correct":3,"explanation":"\"brain\" means: the organ in your head used for thinking"},{"type":"mc","question":"What does \"empathy\" mean in this lesson?","options":["the organ in your head used for thinking","the ability to create ideas or pictures in your mind","the ability to understand other people’s feelings","to influence how something develops"],"correct":2,"explanation":"\"empathy\" means: the ability to understand other people’s feelings"},{"type":"mc","question":"What does \"imagination\" mean in this lesson?","options":["the ability to understand other people’s feelings","the ability to create ideas or pictures in your mind","to influence how something develops","the organ in your head used for thinking"],"correct":1,"explanation":"\"imagination\" means: the ability to create ideas or pictures in your mind"}]'::jsonb,
  'Understand and discuss how reading shapes your brain using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

