insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_life_another_planet', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260507_searching_for_life_on_another_planet_download.mp3', 365,
  '[{"speaker":"Neil","text":"This is 6 Minute English from BBC Learning English.","startMs":8560,"endMs":11240},{"speaker":"Becca","text":"Neil, do you believe that life exists away from planet Earth?","startMs":13380,"endMs":17400},{"speaker":"Neil","text":"Well, I''m not sure about the kind of little green men that you see in science fiction movies, but also, I think we cannot be alone in the universe.","startMs":17720,"endMs":28220},{"speaker":"Neil","text":"What about you, Becca?","startMs":28380,"endMs":29600},{"speaker":"Becca","text":"I agree, I think that maybe life does exist beyond our planet, but maybe not as we see in alien movies.","startMs":30440,"endMs":38860},{"speaker":"Neil","text":"Well, in this episode, we''ll be learning from science and space experts about whether the conditions for life exist on a planet 40 light years away.","startMs":39580,"endMs":49240},{"speaker":"Becca","text":"Yes, and as usual, you can find a transcript for this episode, along with all the vocabulary and a worksheet, on our website bbclearningenglish.","startMs":49800,"endMs":58880},{"speaker":"Neil","text":"OK, a quiz question for you, Becca.","startMs":60160,"endMs":61680},{"speaker":"Neil","text":"How long would it take to drive a car to the Sun at 100km an hour?","startMs":61760,"endMs":68020},{"speaker":"Neil","text":"Is it: a) 70 years, b) 170 years, or c) 1,700 years?","startMs":68280,"endMs":75600},{"speaker":"Becca","text":"Well, Neil, the Sun seems very far away so I''ll go for c) 1,700 years.","startMs":76080,"endMs":82760},{"speaker":"Neil","text":"I hope you have enough petrol for that.","startMs":83720,"endMs":85480},{"speaker":"Neil","text":"Well, we''ll find out the answer to the question later.","startMs":85660,"endMs":88200},{"speaker":"Neil","text":"Now, though, some science and space experts are excited about a planet in a different solar system from our own.","startMs":88980,"endMs":95220},{"speaker":"Neil","text":"Science journalist, Caroline Steele, talks about this discovery on the BBC World Service programme, What in the World.","startMs":95900,"endMs":102280},{"speaker":"Caroline Steele","text":"So, scientists have been looking at an exoplanet.","startMs":102600,"endMs":105720},{"speaker":"Caroline Steele","text":"So, that''s a planet that exists in a solar system that isn''t our own, called TRAPPIST-1e, um, and it''s a rocky planet like Earth.","startMs":105800,"endMs":114240},{"speaker":"Caroline Steele","text":"It''s a similar size to Earth, and it exists in the habitable zone around its sun, and its sun is called TRAPPIST-1.","startMs":114380,"endMs":122860},{"speaker":"Becca","text":"Caroline explains that scientists have discovered that the planet, TRAPPIST-1e, exists in the habitable zone around its sun.","startMs":123880,"endMs":131920},{"speaker":"Becca","text":"The adjective habitable describes a place or habitat that is suitable for something to live.","startMs":132360,"endMs":137840},{"speaker":"Neil","text":"Yes, and a zone is an area with a particular feature.","startMs":138260,"endMs":141620},{"speaker":"Neil","text":"For example, people who live in earthquake zones have to be prepared for danger.","startMs":141780,"endMs":146420},{"speaker":"Becca","text":"So, a habitable zone is an area where something could live.","startMs":147320,"endMs":151080},{"speaker":"Becca","text":"Caroline goes on to explain why they think TRAPPIST-1e may be habitable.","startMs":151400,"endMs":155700},{"speaker":"Caroline Steele","text":"Scientists have been looking at the potential atmosphere around TRAPPIST-1e and they''ve ruled out that it''s really full of hydrogen or carbon dioxide, which is a great thing because they''re greenhouse gases, which would make the planet really hot.","startMs":155940,"endMs":168280},{"speaker":"Caroline Steele","text":"And there are some small clues that it might be a nitrogen-dominated atmosphere, which, again, is another sort of clue that there could be life there.","startMs":168600,"endMs":178200},{"speaker":"Neil","text":"Caroline Steele says that scientists are looking at the potential atmosphere around TRAPPIST-1e.","startMs":178200,"endMs":183740},{"speaker":"Neil","text":"That is, that they want to find out if the atmosphere is capable or likely to become able to host life.","startMs":184620,"endMs":190460},{"speaker":"Neil","text":"If something has potential, it already has the qualities or abilities to do something.","startMs":190960,"endMs":195740},{"speaker":"Neil","text":"The adjective potential has a similar meaning but refers to future capability.","startMs":196120,"endMs":200940},{"speaker":"Becca","text":"We could say the data has potential in that it shows signs of helping the research.","startMs":202420,"endMs":206840},{"speaker":"Becca","text":"But when we talk about potential data, we''re referring to data that could help us with future research.","startMs":206960,"endMs":212500},{"speaker":"Neil","text":"She also mentions how scientists have ruled out that TRAPPIST-1e is full of hydrogen or carbon dioxide.","startMs":213260,"endMs":219860},{"speaker":"Neil","text":"The phrasal verb rule out means to dismiss the possibility or idea of something.","startMs":220440,"endMs":225140},{"speaker":"Neil","text":"Scientists have found that TRAPPIST-1e is not full of those greenhouse gases, they''ve ruled it out.","startMs":225760,"endMs":231180},{"speaker":"Becca","text":"And Caroline goes on to say how the atmosphere of TRAPPIST-1e is dominated by nitrogen.","startMs":232580,"endMs":237660},{"speaker":"Becca","text":"If something is dominated by something else, it is controlled by it or is the most significant element of it.","startMs":238540,"endMs":244500},{"speaker":"Becca","text":"TRAPPIST-1e is full of nitrogen, which is exciting because nitrogen is a sign of life and habitability.","startMs":244840,"endMs":251520},{"speaker":"Neil","text":"So, what if nitrogen is actually found on this planet?","startMs":252620,"endMs":255900},{"speaker":"Neil","text":"Caroline Steele has more.","startMs":256160,"endMs":257880},{"speaker":"Caroline Steele","text":"My guess is what we''ll do is try and see what other gases are in the atmosphere and use models to work out how warm the planet could be and whether or not it''s a temperature that basically could support life, or maybe it''s too hot or too cold, but fingers crossed it has nitrogen.","startMs":258080,"endMs":271980},{"speaker":"Caroline Steele","text":"There''s enough of it to keep the planet a decent temperature.","startMs":272640,"endMs":275560},{"speaker":"Caroline Steele","text":"And then that''s one step closer to finding life.","startMs":275560,"endMs":278060},{"speaker":"Becca","text":"Caroline guesses that scientists will focus on the planet''s temperature and whether it could support life.","startMs":278220,"endMs":283600},{"speaker":"Becca","text":"She uses the expression fingers crossed to express hope for a positive outcome.","startMs":283840,"endMs":288580},{"speaker":"Neil","text":"We often make the physical gesture of crossing our fingers for good luck.","startMs":289500,"endMs":293380},{"speaker":"Becca","text":"That reminds me Neil, the answer to your question!","startMs":294560,"endMs":297020},{"speaker":"Becca","text":"Fingers crossed that I answered correctly.","startMs":297260,"endMs":299020},{"speaker":"Neil","text":"I see what you''ve done there, Becca.","startMs":299720,"endMs":301000},{"speaker":"Neil","text":"Yes, I asked you how long it would take to drive to the Sun at 100km an hour, and you answered c) 1,700 years.","startMs":301360,"endMs":310080},{"speaker":"Neil","text":"Well, the Sun is very far away, but the answer was b) only 170 years.","startMs":310580,"endMs":316060},{"speaker":"Becca","text":"Oh well, that''s still longer than my lifetime!","startMs":316240,"endMs":318840},{"speaker":"Becca","text":"Now let''s have a recap of the language we''ve learnt in this episode, starting with habitable, which describes a place or habitat that is suitable for something to live.","startMs":319500,"endMs":328360},{"speaker":"Neil","text":"A zone is an area with a particular feature.","startMs":328580,"endMs":331160},{"speaker":"Becca","text":"Potential describes possibly having qualities or abilities to do something.","startMs":331440,"endMs":335440},{"speaker":"Neil","text":"The phrasal verb rule out means to dismiss the possibility or idea of something.","startMs":335840,"endMs":340600},{"speaker":"Becca","text":"We also had dominated.","startMs":340980,"endMs":342900},{"speaker":"Becca","text":"If something is dominated by something else, it is controlled by it or is the most significant element of it.","startMs":343400,"endMs":349460},{"speaker":"Neil","text":"And finally, the expression fingers crossed is used to wish for hope or luck.","startMs":350260,"endMs":355100},{"speaker":"Neil","text":"Once again, our six minutes are up, but head over to our website, Goodbye for now.","startMs":355520,"endMs":364500},{"speaker":"Becca","text":"Bye!","startMs":364660,"endMs":364920}]'::jsonb,
  'Understand and discuss searching for life on another planet using BBC natural English. You''ll pick up useful words like planet, alien life, telescope. Listen to Neil & Beth talk it through in natural English.',
  '["Neil, do you believe that life exists away from planet Earth?","Well, I''m not sure about the kind of little green men that you see in science fiction movies, but also, I think we cannot be alone in the universe.","I agree, I think that maybe life does exist beyond our planet, but maybe not as we see in alien movies."]'::jsonb,
  '[{"word":"planet","phonetic":"","pos":"Noun","translation":"sayyora","definition":"a large round object in space that moves around a star","example":"Neil, do you believe that life exists away from planet Earth?"},{"word":"alien life","phonetic":"","pos":"Noun phrase","translation":"begona sayyoradagi hayot","definition":"life from outside Earth","example":"I agree, I think that maybe life does exist beyond our planet, but maybe not as we see in alien movies."},{"word":"telescope","phonetic":"","pos":"Noun","translation":"teleskop","definition":"a device used to see distant objects in space","example":"Neil, do you believe that life exists away from planet Earth?"},{"word":"atmosphere","phonetic":"","pos":"Noun","translation":"atmosfera","definition":"the layer of gases around a planet","example":"Scientists have been looking at the potential atmosphere around TRAPPIST-1e and they''ve ruled out that it''s really full of hydrogen or carbon dioxide, which is a great thing because they''re greenhouse gases, which would make the planet really hot."},{"word":"evidence","phonetic":"","pos":"Noun","translation":"dalil","definition":"facts that show something may be true","example":"Neil, do you believe that life exists away from planet Earth?"},{"word":"search for","phonetic":"","pos":"Phrasal verb","translation":"qidirmoq","definition":"to try to find something","example":"We could say the data has potential in that it shows signs of helping the research."}]'::jsonb,
  '[{"type":"mc","question":"What does \"planet\" mean in this lesson?","options":["a large round object in space that moves around a star","life from outside Earth","a device used to see distant objects in space","the layer of gases around a planet"],"correct":0,"explanation":"\"planet\" means: a large round object in space that moves around a star"},{"type":"mc","question":"What does \"alien life\" mean in this lesson?","options":["a large round object in space that moves around a star","a device used to see distant objects in space","the layer of gases around a planet","life from outside Earth"],"correct":3,"explanation":"\"alien life\" means: life from outside Earth"},{"type":"mc","question":"What does \"telescope\" mean in this lesson?","options":["life from outside Earth","the layer of gases around a planet","a device used to see distant objects in space","a large round object in space that moves around a star"],"correct":2,"explanation":"\"telescope\" means: a device used to see distant objects in space"},{"type":"mc","question":"What does \"atmosphere\" mean in this lesson?","options":["a device used to see distant objects in space","the layer of gases around a planet","a large round object in space that moves around a star","life from outside Earth"],"correct":1,"explanation":"\"atmosphere\" means: the layer of gases around a planet"}]'::jsonb,
  'Understand and discuss searching for life on another planet using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

