insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_cowboy_way_life', 'https://downloads.bbc.co.uk/learningenglish/features/OWIE/260213_OWIE_the_battle_for_the_cowboy_way_of_life_download.mp3', 736,
  '[{"speaker":"Pippa","text":"At the BBC, our colleagues investigate important stories around the world.","startMs":3140,"endMs":7780},{"speaker":"Pippa","text":"In this special series, Our World in English, we’re bringing you the best documentaries from the BBC in language you can understand.","startMs":8580,"endMs":15900},{"speaker":"Pippa","text":"This episode is called The battle for the cowboy way of life.","startMs":16760,"endMs":20320},{"speaker":"Ellie","text":"I hop into Brud''s dusty 4x4 truck.","startMs":24180,"endMs":26520},{"speaker":"Pippa","text":"BBC Journalist Ellie House has travelled to Montana in the United States.","startMs":27500,"endMs":32240},{"speaker":"Pippa","text":"Montana is a western US state that goes all the way up to the Canadian border.","startMs":32940,"endMs":37740},{"speaker":"Pippa","text":"You might have seen old western movies set in places like this.","startMs":38480,"endMs":42740},{"speaker":"Pippa","text":"Montana is full of wide open spaces with huge areas of flat land.","startMs":43060,"endMs":48380},{"speaker":"Pippa","text":"In these films you’ll find cowboys, with wide brim hats and guns, who enjoy the outdoors, horses, farming.","startMs":49380,"endMs":57100},{"speaker":"Pippa","text":"And a modern cowboy way of life still exists here.","startMs":57800,"endMs":60860},{"speaker":"Pippa","text":"Ellie’s being shown around by Brud Smith.","startMs":62020,"endMs":63820},{"speaker":"Brud","text":"Do you see where the brown is over there?","startMs":64520,"endMs":66540},{"speaker":"Brud","text":"Where it starts out there?","startMs":66700,"endMs":67760},{"speaker":"Ellie","text":"Yeah.","startMs":67780,"endMs":68120},{"speaker":"Brud","text":"That''s the edge of our ranch there.","startMs":68140,"endMs":69620},{"speaker":"Brud","text":"And we probably go over to where the trees, just the side of the, the big trees down there.","startMs":70160,"endMs":76740},{"speaker":"Pippa","text":"A ranch is a very large farm.","startMs":77540,"endMs":79800},{"speaker":"Pippa","text":"Brud’s family have owned a ranch here for five generations, farming cattle, which means cows.","startMs":80480,"endMs":86120},{"speaker":"Pippa","text":"And Brud’s ranch relies on his own private land… The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026","startMs":87080,"endMs":89960},{"speaker":"Brud","text":"And actually, that''s private land up to that sign up there.","startMs":90800,"endMs":94520},{"speaker":"Pippa","text":"And federal land, owned by the national government…","startMs":94820,"endMs":97480},{"speaker":"Brud","text":"But the this is all federal land here.","startMs":99520,"endMs":101500},{"speaker":"Brud","text":"And then it''s federal land beyond that.","startMs":101500,"endMs":103080},{"speaker":"Pippa","text":"In the US, each state has its own government, but the national leadership, currently headed up by President Trump, is the federal government in Washington DC.","startMs":105640,"endMs":114920},{"speaker":"Pippa","text":"About 30% of Montana is owned by the federal government.","startMs":116520,"endMs":120280},{"speaker":"Pippa","text":"This land is often called public or federal land.","startMs":121040,"endMs":123960},{"speaker":"Pippa","text":"And this land is at the centre of a debate.","startMs":124680,"endMs":127020},{"speaker":"Pippa","text":"Some think the government shouldn’t own so much and that parts of it should be sold or transferred to the state authorities.","startMs":127780,"endMs":134000},{"speaker":"Pippa","text":"But Brud says access to this land, and keeping it publicly owned, is important for his ranch.","startMs":134760,"endMs":140340},{"speaker":"Pippa","text":"This is the story of the modern day cowboys that live in Montana, and whether the public land they use, and the way they live, is under threat.","startMs":140900,"endMs":149660},{"speaker":"Pippa","text":"Brud takes BBC reporter Ellie House to see some of the public land he wants to protect.","startMs":152560,"endMs":157080},{"speaker":"Ellie","text":"So this, is this is public land.","startMs":157940,"endMs":159680},{"speaker":"Ellie","text":"So, explain to me how it works.","startMs":159700,"endMs":161180},{"speaker":"Ellie","text":"The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026","startMs":161180,"endMs":161220},{"speaker":"Brud","text":"Well, we have a permit, a certain amount that we could run up here on a forest permit during the months of middle of June to the middle of October.","startMs":161220,"endMs":169780},{"speaker":"Pippa","text":"Brud rents this land from the government, so that his cattle can graze up here in the summer.","startMs":171100,"endMs":175320},{"speaker":"Pippa","text":"35 for each cow every month, much cheaper than renting private land.","startMs":177720,"endMs":181820},{"speaker":"Ellie","text":"How important is having access to this public land for your business?","startMs":182460,"endMs":185260},{"speaker":"Brud","text":"Incredibly important because without it, you would have to cut down your operation as to the number of cattle you run, and most of the time you''re running kind of on a margin.","startMs":187140,"endMs":197200},{"speaker":"Brud","text":"The cost of running a ranch, unfortunately, is very high too.","startMs":197200,"endMs":200320},{"speaker":"Brud","text":"Equipment''s high, fuel''s high, all that.","startMs":200580,"endMs":203940},{"speaker":"Ellie","text":"So the ranching industry here really relies on having access to public land?","startMs":204120,"endMs":207100},{"speaker":"Brud","text":"Oh definitely, definitely","startMs":207330,"endMs":208740},{"speaker":"Pippa","text":"But some politicians believe parts of the public land should be sold.","startMs":209080,"endMs":212940},{"speaker":"Pippa","text":"One US Senator, called Mike Lee, campaigned for President Trump to support a plan to sell off up to three million acres of public land in the west, for housebuilding amid a nationwide shortage.","startMs":213480,"endMs":224560},{"speaker":"Pippa","text":"Here he is talking about the idea in a promotional video published on the social media platform X.","startMs":225280,"endMs":231220},{"speaker":"Pippa","text":"The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026 Senator Mike Lee (promotional video) Nearly one out of every three acres in America is owned by the federal government.","startMs":231500,"endMs":235900},{"speaker":"Pippa","text":"In states like Utah, it''s even more extreme.","startMs":236160,"endMs":238540},{"speaker":"Pippa","text":"Almost 70% of our land is controlled by Washington, D.","startMs":239060,"endMs":242400},{"speaker":"Pippa","text":"That''s not sustainable.","startMs":243640,"endMs":244780},{"speaker":"Pippa","text":"It''s not serving the Americans who actually live here.","startMs":246120,"endMs":249980},{"speaker":"Pippa","text":"Senator Lee’s plan faced a big backlash in Montana.","startMs":250360,"endMs":253740},{"speaker":"Pippa","text":"A backlash is when people feel and argue strongly against a political change or plan.","startMs":254340,"endMs":259620},{"speaker":"Pippa","text":"Lots of people want to keep the federal land public.","startMs":260140,"endMs":263380},{"speaker":"Pippa","text":"Ellie met Tracy-Stone- Manning by a stream on public land near the city of Missoula in Montana.","startMs":263740,"endMs":269900},{"speaker":"Ellie","text":"Wow.","startMs":271320,"endMs":271980},{"speaker":"Tracy","text":"That was a mother whitetail deer and her fawn still with spots.","startMs":272180,"endMs":277200},{"speaker":"Ellie","text":"They were just galloping in front of us.","startMs":278140,"endMs":279140},{"speaker":"Tracy","text":"Just galloped away from us.","startMs":279140,"endMs":279540},{"speaker":"Pippa","text":"Tracy was head of the Bureau of Land Management under the previous US president, Joe Biden.","startMs":280780,"endMs":286200},{"speaker":"Pippa","text":"She’s now in charge of the Wilderness Society, which is an environmental conservation organisation.","startMs":286500,"endMs":291180},{"speaker":"Tracy","text":"The current administration under President Trump talks about our public lands in the form of a balance sheet.","startMs":292540,"endMs":298600},{"speaker":"Tracy","text":"That kind of language and that kind of approach is about today''s profits, not about what we need to pay forward to the future so that The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026 future generations have the ability to access and touch nature, have the ability to hunt and fish and camp and birdwatch and picnic like, like we do.","startMs":299140,"endMs":319940},{"speaker":"Pippa","text":"Senator Lee’s plan didn’t include national parks, monuments or protected wilderness areas.","startMs":320500,"endMs":325860},{"speaker":"Pippa","text":"He insisted it only covered a tiny portion of land, close to existing towns or cities.","startMs":326320,"endMs":331420},{"speaker":"Pippa","text":"But many people believe that once some public land is sold, more could follow.","startMs":331800,"endMs":336040},{"speaker":"Ellie","text":"Senator Lee was pretty clear that it would be maximum 0.","startMs":336940,"endMs":340480},{"speaker":"Ellie","text":"75% of public lands that would be eligible for sale, which is a pretty small percentage.","startMs":342580,"endMs":349120},{"speaker":"Tracy","text":"The idea that this year they’re just going to sell off just 3 million acres… what about next year?","startMs":350960,"endMs":359960},{"speaker":"Tracy","text":"And what about the year after that?","startMs":360220,"endMs":361620},{"speaker":"Tracy","text":"If you do that every year for a hundred years, you don''t have public lands left, right?","startMs":362080,"endMs":365540},{"speaker":"Tracy","text":"So I think that''s really what drove the backlash, people understanding this was the beginning of a very bad idea.","startMs":366720,"endMs":377840},{"speaker":"Pippa","text":"In the end, Senator Lee faced opposition to his proposal and was forced to stop his plan.","startMs":378240,"endMs":383220},{"speaker":"Pippa","text":"But Tracy believes he won’t give up.","startMs":383700,"endMs":385400},{"speaker":"Tracy","text":"Senator Lee, when he withdrew his language, was very clear that he wasn''t done.","startMs":386000,"endMs":390340},{"speaker":"Tracy","text":"So the threat of losing this identity that we have in common as Americans that we have this cherished thing called public lands is real and the risk to tinkering with that is more risk than reward.","startMs":390620,"endMs":406880},{"speaker":"Pippa","text":"The BBC tried to speak with Senator Lee, but he didn’t respond to the interview request.","startMs":407800,"endMs":412280},{"speaker":"Pippa","text":"The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026 And some people do think that the federal government owns too much land in western states like Montana.","startMs":413440,"endMs":418500},{"speaker":"William","text":"The United States government owns one third of the country, 640 million acres.","startMs":418940,"endMs":424260},{"speaker":"William","text":"Most of that''s in the American west.","startMs":425000,"endMs":427320},{"speaker":"Pippa","text":"This is lawyer William Perry Pendley.","startMs":427460,"endMs":429800},{"speaker":"Pippa","text":"William is a controversial figure.","startMs":430120,"endMs":432080},{"speaker":"Pippa","text":"He was head of the Bureau of Land Management in Trump’s first term as president, but a judge ruled that he was in the position unlawfully, because his appointment was never confirmed by the Senate.","startMs":432340,"endMs":442400},{"speaker":"Pippa","text":"He was also an author on Project 2025, a conservative plan for Trump’s second presidency.","startMs":442620,"endMs":448040},{"speaker":"William","text":"So when the federal government sneezes, we catch a cold.","startMs":449060,"endMs":452100},{"speaker":"William","text":"We really can''t do anything economically without the permission of the federal government.","startMs":452640,"endMs":457740},{"speaker":"Pippa","text":"William is saying that because so much land in western states is owned by the federal government, it is difficult to build homes and expand businesses in the area.","startMs":458260,"endMs":466640},{"speaker":"Pippa","text":"He points to Las Vegas as an example of where selling public land can create opportunities.","startMs":467100,"endMs":472280},{"speaker":"William","text":"When I was running the Bureau of Land Management for President Trump during his first term, I went down to Las Vegas.","startMs":473340,"endMs":481900},{"speaker":"Pippa","text":"Las Vegas, the casino city in Nevada, is surrounded by federally-owned desert land, making economic growth difficult.","startMs":482340,"endMs":490560},{"speaker":"Pippa","text":"Since the 1990s, some of this land has been sold and built on.","startMs":490940,"endMs":494900},{"speaker":"Pippa","text":"The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026","startMs":494900,"endMs":494920},{"speaker":"William","text":"And I met with a BLM official and he pointed out all the things that were there, housing developments, commercial activity, recreation facilities.","startMs":494920,"endMs":507820},{"speaker":"William","text":"And he said, \"Mr Pendley, I got to tell you, if we had not been authorised to dispose of all of this land, none of this would have been possible, and all this economic activity that you see here would have been prevented\".","startMs":508600,"endMs":522860},{"speaker":"William","text":"I frankly think that fully informed the American people would, would agree with that.","startMs":522940,"endMs":527960},{"speaker":"Pippa","text":"But in Montana, many people are worried that selling public land like this will mean an end to modern ranches, and the cowboy lifestyle.","startMs":528260,"endMs":536260},{"speaker":"Pippa","text":"And even without selling public land, the area is changing.","startMs":537220,"endMs":540860},{"speaker":"Pippa","text":"Country music and the western lifestyle is becoming more popular.","startMs":541620,"endMs":545300},{"speaker":"Pippa","text":"New people are moving in to enjoy the big open spaces and traditional cowboy sports like the rodeo, where people try to stay on the back of an angry bull.","startMs":545700,"endMs":554280},{"speaker":"Pippa","text":"Ellie (at the rodeo) Ooh and he''s off right away.","startMs":554280,"endMs":558920},{"speaker":"Pippa","text":"One place where the new popularity of the cowboy way of life is clear is a city called Bozeman.","startMs":558920,"endMs":568300},{"speaker":"Pippa","text":"BBC reporter Ellie House went to see it.","startMs":568660,"endMs":571400},{"speaker":"Ellie","text":"It is five PM in downtown Bozeman, and I''m standing on the main street.","startMs":571620,"endMs":576300},{"speaker":"Ellie","text":"And this city is the centre of Montana''s development and population boom.","startMs":576300,"endMs":582000},{"speaker":"Ellie","text":"And you can really feel that here.","startMs":582360,"endMs":583460},{"speaker":"Ellie","text":"It''s absolutely buzzing.","startMs":583640,"endMs":584720},{"speaker":"Ellie","text":"It''s almost like a Disney version of the American west.","startMs":585700,"endMs":588180},{"speaker":"Ellie","text":"You''ve got all of the cowboy paraphernalia, but it''s sold for quite high prices next to things like artisanal soap and handcrafted jewellery.","startMs":588500,"endMs":597480},{"speaker":"Pippa","text":"Bozeman is one of America’s fastest-growing cities.","startMs":597780,"endMs":601180},{"speaker":"Pippa","text":"Locals say wealthy Californians are moving in and causing price increases.","startMs":601720,"endMs":607140},{"speaker":"Pippa","text":"The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026 Back on Brud’s ranch, Ellie’s having lunch with the family on the patio.","startMs":608420,"endMs":614940},{"speaker":"Pippa","text":"Brud’s wife, Terry, explains what a changing Montana means to her.","startMs":616260,"endMs":619860},{"speaker":"Terry","text":"And then you get off the plane in Bozeman and there''s all these people with cowboy hats.","startMs":620320,"endMs":624730},{"speaker":"Terry","text":"Well, they have nothing to do with agriculture, nothing to with ranching, nothing to do with really Montana.","startMs":624730,"endMs":629840},{"speaker":"Pippa","text":"Brud’s daughter Darby has just moved back to Montana from New York to take over the ranch from her father.","startMs":631000,"endMs":636660},{"speaker":"Pippa","text":"She also worries about the new developments in the area and the new people who are buying them.","startMs":637160,"endMs":642260},{"speaker":"Darby","text":"It is disheartening to see the larger trends happening to our neighbours and to the land around us.","startMs":642560,"endMs":649260},{"speaker":"Darby","text":"I think because we are in this for the long haul, you know, there''s no, no way that we''re going to sell this place.","startMs":649700,"endMs":657080},{"speaker":"Pippa","text":"Darby says her family are in it for the long haul, meaning plan to stay in Montana for a long time into the future.","startMs":657420,"endMs":664160},{"speaker":"Pippa","text":"And Darby’s worried that, as development continues, whether it’s the sale of public land, or wealthy outsiders moving to the area, Montana won’t feel the same in the future, that it will be sullied, or ruined.","startMs":671500,"endMs":684280},{"speaker":"Darby","text":"Once you pave wilderness, it''s not going to come back.","startMs":687240,"endMs":691720},{"speaker":"Darby","text":"It''s forever that way.","startMs":691800,"endMs":692760},{"speaker":"Darby","text":"And people who buy those sorts of places are trying to get a version of Montana that, we understand, it''s really appealing to feel like you have your own slice of paradise.","startMs":694680,"endMs":705340},{"speaker":"Darby","text":"But you have to realise that in doing that, you''re sullying the very thing that you came for.","startMs":706380,"endMs":712480},{"speaker":"Pippa","text":"Thanks for listening to this episode of Our World in English, based on the documentary The real Yellowstone: A battle for the cowboy way of life from Assignment on the BBC World Service.","startMs":714000,"endMs":725360},{"speaker":"Pippa","text":"The original programme was reported by The battle for the cowboy way of life Our World in English © British Broadcasting Corporation 2026 Ellie House and produced by Josephine Casserly.","startMs":725860,"endMs":730140},{"speaker":"Pippa","text":"You can find more information about Assignment by following the link in the notes below this programme.","startMs":731120,"endMs":736100}]'::jsonb,
  'Understand and discuss the battle for the cowboy way of life using BBC natural English. You''ll pick up useful words like cowboy, way of life, battle. Listen to BBC Narrator talk it through in natural English.',
  '["At the BBC, our colleagues investigate important stories around the world.","In this special series, Our World in English, we’re bringing you the best documentaries from the BBC in language you can understand.","This episode is called The battle for the cowboy way of life."]'::jsonb,
  '[{"word":"cowboy","phonetic":"","pos":"Noun","translation":"kovboy","definition":"a person who works with cattle, often on horseback","example":"This episode is called The battle for the cowboy way of life."},{"word":"way of life","phonetic":"","pos":"Noun phrase","translation":"turmush tarzi","definition":"the typical habits and culture of a group","example":"This episode is called The battle for the cowboy way of life."},{"word":"battle","phonetic":"","pos":"Noun","translation":"kurash","definition":"a serious struggle or fight","example":"This episode is called The battle for the cowboy way of life."},{"word":"ranch","phonetic":"","pos":"Noun","translation":"rancho","definition":"a large farm where cattle are raised","example":"That''s the edge of our ranch there."},{"word":"tradition","phonetic":"","pos":"Noun","translation":"an’ana","definition":"a belief or custom passed through generations","example":"New people are moving in to enjoy the big open spaces and traditional cowboy sports like the rodeo, where people try to stay on the back of an angry bull."},{"word":"survive","phonetic":"","pos":"Verb","translation":"omon qolmoq","definition":"to continue to exist despite difficulty","example":"At the BBC, our colleagues investigate important stories around the world."}]'::jsonb,
  '[{"type":"mc","question":"What does \"cowboy\" mean in this lesson?","options":["a person who works with cattle, often on horseback","the typical habits and culture of a group","a serious struggle or fight","a large farm where cattle are raised"],"correct":0,"explanation":"\"cowboy\" means: a person who works with cattle, often on horseback"},{"type":"mc","question":"What does \"way of life\" mean in this lesson?","options":["a person who works with cattle, often on horseback","a serious struggle or fight","a large farm where cattle are raised","the typical habits and culture of a group"],"correct":3,"explanation":"\"way of life\" means: the typical habits and culture of a group"},{"type":"mc","question":"What does \"battle\" mean in this lesson?","options":["the typical habits and culture of a group","a large farm where cattle are raised","a serious struggle or fight","a person who works with cattle, often on horseback"],"correct":2,"explanation":"\"battle\" means: a serious struggle or fight"},{"type":"mc","question":"What does \"ranch\" mean in this lesson?","options":["a serious struggle or fight","a large farm where cattle are raised","a person who works with cattle, often on horseback","the typical habits and culture of a group"],"correct":1,"explanation":"\"ranch\" means: a large farm where cattle are raised"}]'::jsonb,
  'Understand and discuss the battle for the cowboy way of life using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
