insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_love_warzone', 'https://downloads.bbc.co.uk/learningenglish/features/OWIE/251215_OWIE_love_in_a_warzone_download.mp3', 672,
  '[{"speaker":"Beth","text":"At the BBC, our colleagues investigate important stories from around the world.","startMs":200,"endMs":5100},{"speaker":"Beth","text":"In this new series, Our World in English, we''re bringing you the best documentaries from the BBC in language you can understand.","startMs":5540,"endMs":13920},{"speaker":"Beth","text":"This episode is called Kharkiv: Love in a war zone.","startMs":14540,"endMs":18260},{"speaker":"Adela","text":"I''m at the Polish Ukrainian border.","startMs":18860,"endMs":26920},{"speaker":"Adela","text":"It''s hot outside, 33 degrees.","startMs":27380,"endMs":31000},{"speaker":"Adela","text":"I''ve been waiting here for more than four hours in a queue.","startMs":32560,"endMs":35540},{"speaker":"Adela","text":"They work really slowly here.","startMs":36440,"endMs":38320},{"speaker":"Adela","text":"This is the longest time I''ve been ever waiting on my way to Ukraine.","startMs":39060,"endMs":44720},{"speaker":"Adela","text":"But anyway, I can''t wait to be with Kostya.","startMs":46160,"endMs":47860},{"speaker":"Beth","text":"This is Adela Knapova a Czech writer and journalist.","startMs":49580,"endMs":53280},{"speaker":"Beth","text":"She''s stuck in a queue to cross the border into Ukraine.","startMs":53780,"endMs":57180},{"speaker":"Adela","text":"It looks like it''s my turn to go, to move another two metres, so I''m going to do it now.","startMs":61260,"endMs":68880},{"speaker":"Adela","text":"I just can''t wait to be with Kostya.","startMs":70440,"endMs":71840},{"speaker":"Adela","text":"To be honest, we are all tired.","startMs":73500,"endMs":77080},{"speaker":"Adela","text":"Everyone here is tired.","startMs":77260,"endMs":78360},{"speaker":"Beth","text":"Adela is travelling to Kharkiv in eastern Ukraine, close to the border with Russia.","startMs":80120,"endMs":85820},{"speaker":"Beth","text":"Kharkiv is one of the most bombed cities in Ukraine.","startMs":86840,"endMs":90100},{"speaker":"Beth","text":"Adela moved to Kharkiv around a year ago after she met an artist called Konstantin Zorkin, who she calls Kostya.","startMs":90840,"endMs":98200},{"speaker":"Beth","text":"She left her life in Prague and moved to Kharkiv to be with Kostya.","startMs":101360,"endMs":104660},{"speaker":"Adela","text":"If someone told me even one year ago that I will live in Kharkiv, that I will fell in love, and that I will be happy in Kharkiv, and that I will leave all my Prague life for Kharkiv, I would consider that person a crazy man or woman.","startMs":106400,"endMs":126280},{"speaker":"Adela","text":"I just I would say it''s no way, no way.","startMs":126320,"endMs":130440},{"speaker":"Adela","text":"Love in a war zone Our World in English © British Broadcasting Corporation 2025","startMs":130440,"endMs":138740},{"speaker":"Beth","text":"How far would you go for love?","startMs":138740,"endMs":140760},{"speaker":"Beth","text":"Over the past year, BBC Eye has been speaking to people in Kharkiv.","startMs":141160,"endMs":146120},{"speaker":"Beth","text":"In this programme, we''re going to tell one story about Adela and Konstantin and what their life in Kharkiv is like as the war in Ukraine continues.","startMs":147280,"endMs":157580},{"speaker":"Beth","text":"Adela''s friends in Prague want her to come home, but Adela wants to be with Kostya, and Kostya feels he needs to stay in Kharkiv.","startMs":162400,"endMs":172130},{"speaker":"Adela","text":"When I''m in Prague, they almost always ask me, why don''t you bring Konstantin with you?","startMs":174480,"endMs":180040},{"speaker":"Adela","text":"But I say he doesn''t want to live here.","startMs":181060,"endMs":182740},{"speaker":"Adela","text":"They don''t want to run away.","startMs":186730,"endMs":188540},{"speaker":"Beth","text":"Kharkiv is a dangerous place to live.","startMs":189480,"endMs":192080},{"speaker":"Adela","text":"Of course, if Russians enter Kharkiv, there is no place for us.","startMs":194540,"endMs":197530},{"speaker":"Adela","text":"We will be killed, both of us.","startMs":197530,"endMs":199240},{"speaker":"Adela","text":"The, the reality of the war is is like this.","startMs":201020,"endMs":204540},{"speaker":"Adela","text":"But as long as Kharkiv is and the Russian bombing and the war is going on, that''s, uh, my place.","startMs":204580,"endMs":211540},{"speaker":"Adela","text":"That''s my home, because it''s, uh, it''s Kostya''s home.","startMs":211740,"endMs":213780},{"speaker":"Beth","text":"By the middle of May 2025, independent monitors say 1,684 civilians had been killed in the Kharkiv region during the war, and there had been over 23,079 attacks.","startMs":227580,"endMs":242720},{"speaker":"Beth","text":"This is Konstantin''s art studio in a basement.","startMs":245600,"endMs":248880},{"speaker":"Beth","text":"This is where Adela and Kostya first met.","startMs":249380,"endMs":252220},{"speaker":"Beth","text":"Sitting at the table, Kostya talks about meeting Adela.","startMs":252860,"endMs":256200},{"speaker":"Beth","text":"Konstantin (translated and spoken by an English speaker) We were sitting at this table talking about Kharkiv, about the feeling in the city.","startMs":256580,"endMs":264360},{"speaker":"Beth","text":"And Adela sat on the chair that I''m sitting on now.","startMs":264660,"endMs":267040},{"speaker":"Beth","text":"And I don''t let anyone sit on this chair except for me.","startMs":267600,"endMs":270400},{"speaker":"Beth","text":"And there were two journalists here, and I felt very tense, and I just started talking to her.","startMs":270400,"endMs":276780},{"speaker":"Beth","text":"I looked at her and she looked at me, and I remember Love in a war zone Our World in English © British Broadcasting Corporation 2025 it as this magical story, because I hardly ever left this basement.","startMs":277020,"endMs":284620},{"speaker":"Beth","text":"There was so much death around.","startMs":285080,"endMs":286760},{"speaker":"Beth","text":"I worked all the time and love, warmth found me.","startMs":286900,"endMs":290700},{"speaker":"Beth","text":"A month after that meeting in Kostya''s studio, Adela moved to Kharkiv.","startMs":293200,"endMs":298120},{"speaker":"Beth","text":"They''ve been together ever since.","startMs":298380,"endMs":300080},{"speaker":"Adela","text":"My closest friends say that Kharkiv has changed me.","startMs":302420,"endMs":306860},{"speaker":"Adela","text":"I have different eyes, they say.","startMs":307180,"endMs":309300},{"speaker":"Adela","text":"I don''t know, I''m not aware of it.","startMs":310660,"endMs":312800},{"speaker":"Adela","text":"I have a unique position.","startMs":313960,"endMs":315460},{"speaker":"Adela","text":"Half inside, half outside.","startMs":315460,"endMs":317580},{"speaker":"Adela","text":"I can run to safety at any time.","startMs":318100,"endMs":320520},{"speaker":"Adela","text":"Sometimes I even feel guilty for that.","startMs":321320,"endMs":323920},{"speaker":"Adela","text":"But as long as Kostya is here in Kharkiv, I have no choice but to live here with him.","startMs":324980,"endMs":331140},{"speaker":"Adela","text":"He never asked me to live here with him.","startMs":332160,"endMs":334420},{"speaker":"Adela","text":"He always repeats that he is aware of the risks I''m taking.","startMs":334920,"endMs":339720},{"speaker":"Adela","text":"But I won''t lie, somewhere deep beneath all that life, love, happiness, hope and gratitude, well, there is a sadness.","startMs":341240,"endMs":352680},{"speaker":"Adela","text":"I think I haven''t admitted it aloud to anyone yet.","startMs":354460,"endMs":359200},{"speaker":"Beth","text":"Two weeks later, in the early hours of the 7th of June, Kharkiv is hit by one of the most powerful drone and missile attacks of the war.","startMs":365640,"endMs":380380},{"speaker":"Beth","text":"It comes five days after a Ukrainian attack on a Russian air base.","startMs":382220,"endMs":386020},{"speaker":"Adela","text":"What you hear is the Shaheds and the Ukrainian army trying to shoot them down.","startMs":392360,"endMs":398360},{"speaker":"Adela","text":"It''s more than 40 explosions during the night here.","startMs":398360,"endMs":402680},{"speaker":"Adela","text":"Rockets, ballistic missiles and dozens of Shaheds.","startMs":402720,"endMs":405860},{"speaker":"Adela","text":"It''s the biggest Russian attack on Kharkiv during the war.","startMs":407680,"endMs":412440},{"speaker":"Adela","text":"What we''re experiencing this night, it''s not even four in the morning.","startMs":413040,"endMs":417620},{"speaker":"Beth","text":"And Adela doesn''t know whether to stay in Kharkiv.","startMs":425800,"endMs":429000},{"speaker":"Beth","text":"Love in a war zone Our World in English © British Broadcasting Corporation 2025","startMs":429000,"endMs":429900},{"speaker":"Adela","text":"When the last explosions, Kostya told me that he will help me pack my stuff and I should leave, but I can''t leave.","startMs":429900,"endMs":441180},{"speaker":"Adela","text":"I want to stay with him.","startMs":441640,"endMs":442880},{"speaker":"Adela","text":"But at the same time, I feel like I need to calm down, to breathe.","startMs":442940,"endMs":448640},{"speaker":"Beth","text":"Later in their kitchen, Adela and Kostya are cooking lunch.","startMs":451120,"endMs":455420},{"speaker":"Beth","text":"It''s small, everyday routines like this, Kostya tells us, that help you survive.","startMs":456400,"endMs":461760},{"speaker":"Beth","text":"Konstantin (translated and spoken by an English speaker) In this chaos, the only thing that you feel you can do is to live your life while you can.","startMs":462280,"endMs":471760},{"speaker":"Beth","text":"Live your life, love, work, and make some kind of contribution to what''s happening.","startMs":472580,"endMs":476920},{"speaker":"Beth","text":"In June, Adela leaves Kharkiv to spend a month in Greece in a house she owns by the sea.","startMs":479100,"endMs":485340},{"speaker":"Beth","text":"Meanwhile, the attacks on Kharkiv continue.","startMs":486060,"endMs":488540},{"speaker":"Beth","text":"When Adela returns to Kharkiv, US President Donald Trump announces he will meet Russian President Vladimir Putin to try to find an end to the war.","startMs":493520,"endMs":503740},{"speaker":"Beth","text":"BBC News headline Donald Trump and Vladimir Putin arrived in Anchorage in Alaska a couple of hours ago, greeting each other on a red carpet laid out at a US Air Force base.","startMs":504060,"endMs":513380},{"speaker":"Beth","text":"It''s the first time they''ve met face to face since 2019.","startMs":513740,"endMs":516860},{"speaker":"Beth","text":"Two days later, Ukrainian President Volodymyr Zelensky and European leaders fly to Washington for more talks about peace.","startMs":517620,"endMs":526120},{"speaker":"Beth","text":"BBC News headline Donald Trump has confirmed the US would be involved in security guarantees for Ukraine as part of a deal to end the war with Russia.","startMs":526980,"endMs":534940},{"speaker":"Beth","text":"Love in a war zone Our World in English © British Broadcasting Corporation 2025","startMs":534940,"endMs":535360},{"speaker":"Beth","text":"That weekend, Adela and Kostya are hosting a small party to celebrate their birthdays.","startMs":535360,"endMs":541160},{"speaker":"Beth","text":"Adela has been watching the news about the negotiations between President Trump, President Putin, President Zelensky and European leaders.","startMs":543320,"endMs":559980},{"speaker":"Beth","text":"But living in Kharkiv, she finds it difficult to believe that the war will end soon.","startMs":560220,"endMs":565420},{"speaker":"Adela","text":"Right now, I feel like there are two realities.","startMs":566760,"endMs":570380},{"speaker":"Adela","text":"The reality outside Ukraine and Putin and Trump and Zelensky and the European leaders are talking and they''re pretending that peace is coming, but it''s just blah, blah, blah.","startMs":571400,"endMs":585820},{"speaker":"Adela","text":"Because here in Ukraine, nothing has changed.","startMs":585920,"endMs":588340},{"speaker":"Adela","text":"The peace is not closer.","startMs":588760,"endMs":590300},{"speaker":"Adela","text":"So for now, the reason I stay here in Kharkiv is the same as why I moved here.","startMs":595540,"endMs":605880},{"speaker":"Adela","text":"I simply feel I''m exactly where I''m supposed to be.","startMs":608380,"endMs":611260},{"speaker":"Adela","text":"And with a man who is the love of my life.","startMs":611260,"endMs":614420},{"speaker":"Adela","text":"You know, the death is inevitable.","startMs":615900,"endMs":618520},{"speaker":"Adela","text":"Our only freedom is to choose to live our own way.","startMs":620000,"endMs":623600},{"speaker":"Beth","text":"Thanks for listening to this episode of Our World in English, based on the documentary Kharkiv: Love in a War Zone by BBC Eye.","startMs":639240,"endMs":647320},{"speaker":"Beth","text":"This programme was originally broadcast in September 2025.","startMs":648500,"endMs":652680},{"speaker":"Beth","text":"Since then, bombings in Kharkiv have continued and more of the city has been destroyed.","startMs":653660,"endMs":659400},{"speaker":"Beth","text":"Talks to end the fighting have also carried on, but for now, the war continues.","startMs":659740,"endMs":665160},{"speaker":"Beth","text":"You can find more information about BBC Eye by following the link in the notes below this programme.","startMs":666200,"endMs":672160}]'::jsonb,
  'Understand and discuss love in a war zone using BBC natural English. You''ll pick up useful words like war zone, conflict, refuge. Listen to BBC Narrator talk it through in natural English.',
  '["At the BBC, our colleagues investigate important stories from around the world.","In this new series, Our World in English, we''re bringing you the best documentaries from the BBC in language you can understand.","I''ve been waiting here for more than four hours in a queue."]'::jsonb,
  '[{"word":"war zone","phonetic":"","pos":"Noun phrase","translation":"urush hududi","definition":"an area where fighting is happening","example":"This episode is called Kharkiv: Love in a war zone."},{"word":"conflict","phonetic":"","pos":"Noun","translation":"mojaro","definition":"a serious disagreement or fight","example":"At the BBC, our colleagues investigate important stories from around the world."},{"word":"refuge","phonetic":"","pos":"Noun","translation":"boshpana","definition":"shelter or protection from danger","example":"At the BBC, our colleagues investigate important stories from around the world."},{"word":"separation","phonetic":"","pos":"Noun","translation":"ajralish","definition":"being apart from someone","example":"At the BBC, our colleagues investigate important stories from around the world."},{"word":"resilience","phonetic":"","pos":"Noun","translation":"bardoshlilik","definition":"the ability to recover from difficulty","example":"At the BBC, our colleagues investigate important stories from around the world."},{"word":"reunite","phonetic":"","pos":"Verb","translation":"qayta birlashmoq","definition":"to come together again after being apart","example":"At the BBC, our colleagues investigate important stories from around the world."}]'::jsonb,
  '[{"type":"mc","question":"What does \"war zone\" mean in this lesson?","options":["an area where fighting is happening","a serious disagreement or fight","shelter or protection from danger","being apart from someone"],"correct":0,"explanation":"\"war zone\" means: an area where fighting is happening"},{"type":"mc","question":"What does \"conflict\" mean in this lesson?","options":["an area where fighting is happening","shelter or protection from danger","being apart from someone","a serious disagreement or fight"],"correct":3,"explanation":"\"conflict\" means: a serious disagreement or fight"},{"type":"mc","question":"What does \"refuge\" mean in this lesson?","options":["a serious disagreement or fight","being apart from someone","shelter or protection from danger","an area where fighting is happening"],"correct":2,"explanation":"\"refuge\" means: shelter or protection from danger"},{"type":"mc","question":"What does \"separation\" mean in this lesson?","options":["shelter or protection from danger","being apart from someone","an area where fighting is happening","a serious disagreement or fight"],"correct":1,"explanation":"\"separation\" means: being apart from someone"}]'::jsonb,
  'Understand and discuss love in a war zone using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

