insert into public.podcast_details (content_item_id, audio_url, duration_seconds, transcript, summary, takeaways, vocabulary, quiz, reflection) values (
  'pod_bbc_ultra_processed_food', 'https://downloads.bbc.co.uk/learningenglish/features/6min/260430_6_minute_english_should_we_eat_ultra_processed_food_download.mp3', 366,
  '[{"speaker":"Phil","text":"This is 6 Minute English from BBC Learning English.","startMs":8660,"endMs":11860},{"speaker":"Pippa","text":"And I''m Pippa.","startMs":12220,"endMs":13460},{"speaker":"Phil","text":"If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners.","startMs":13760,"endMs":23820},{"speaker":"Phil","text":"Ultra-processed foods are everywhere, from sliced bread to chocolate biscuits and crisps.","startMs":25120,"endMs":29810},{"speaker":"Pippa","text":"They might taste good, but the bad news is that ultra-processed foods have been linked to poor health.","startMs":29810,"endMs":36620},{"speaker":"Pippa","text":"They often contain lots of sugar and salt and have been linked to problems like obesity and diabetes.","startMs":36960,"endMs":43040},{"speaker":"Pippa","text":"So, how can we tell what food is ultra- processed and what''s not?","startMs":43780,"endMs":47740},{"speaker":"Pippa","text":"Here''s health reporter Annabel Rackham on BBC World Service programme What in the World?","startMs":48080,"endMs":53080},{"speaker":"Annabel Rackham","text":"Ultra-processed foods are things that contain five or more ingredients, and things that you wouldn''t find in your average kitchen.","startMs":53360,"endMs":61220},{"speaker":"Annabel Rackham","text":"It''s going to have things on there, like emulsifiers, preservatives, additives, dyes and sweeteners.","startMs":61560,"endMs":66660},{"speaker":"Phil","text":"Annabel describes ultra-processed foods as things containing ingredients you wouldn''t find in your kitchen.","startMs":67100,"endMs":73440},{"speaker":"Phil","text":"Do you eat much ultra-processed food, Pippa, or do you try to avoid it?","startMs":74300,"endMs":78340},{"speaker":"Pippa","text":"I used to eat a lot of ultra-processed foods, and now I try to cook everything myself and not eat things like chocolate and snacks all day.","startMs":78520,"endMs":90300},{"speaker":"Phil","text":"I try to cook things using just normal ingredients, just so you know what''s gone into it.","startMs":92560,"endMs":97740},{"speaker":"Pippa","text":"In this episode, we''ll be discussing ultra-processed food as well as learning some useful new vocabulary.","startMs":97900,"endMs":104240},{"speaker":"Pippa","text":"And remember, there''s also a quiz and worksheet available on our website, bbclearningenglish.","startMs":104780,"endMs":109500},{"speaker":"Phil","text":"But now I have a question for you, Pippa.","startMs":112180,"endMs":115040},{"speaker":"Phil","text":"Fizzy drinks, like cola and lemonade, are another example of popular ultra-processed foods, but when were fizzy drinks invented?","startMs":115300,"endMs":124860},{"speaker":"Phil","text":"Was it: a) 1772, b) 1872, or c) 1972?","startMs":125180,"endMs":134080},{"speaker":"Pippa","text":"Well, I think it was before 1972, but 1772 sounds like too early, so I''m going to say b) 1872.","startMs":135160,"endMs":146180},{"speaker":"Phil","text":"We''ll find out the answer at the end of the programme.","startMs":146620,"endMs":149680},{"speaker":"Phil","text":"One reason for the popularity of ultra-processed food is convenience.","startMs":150120,"endMs":154580},{"speaker":"Phil","text":"Let''s hear more from health reporter Annabel, who talks here with Hannah Gelbart, presenter of BBC World Service''s What in the World.","startMs":155320,"endMs":163400},{"speaker":"Annabel Rackham","text":"So, I do think convenience – it is the main issue there.","startMs":163880,"endMs":166860},{"speaker":"Annabel Rackham","text":"And again, with a ready meal, you put it in the microwave for a couple of minutes.","startMs":167040,"endMs":170200},{"speaker":"Annabel Rackham","text":"Whereas, you know, sometimes cooking a fresh meal from scratch – that can take a really long time.","startMs":172720,"endMs":177180},{"speaker":"Hannah Gelbart","text":"What''s your ultra-processed guilty food?","startMs":177260,"endMs":179340},{"speaker":"Annabel Rackham","text":"I''m a chocolate girl.","startMs":179640,"endMs":180660},{"speaker":"Annabel Rackham","text":"A packet of biscuits – something like that.","startMs":181100,"endMs":184580},{"speaker":"Annabel Rackham","text":"that''s my guilty pleasure.","startMs":185080,"endMs":185960},{"speaker":"Pippa","text":"Ultra-processed foods like ready meals are convenient.","startMs":186500,"endMs":189840},{"speaker":"Pippa","text":"A ready meal is a meal from a supermarket that has already been prepared and can be heated up quickly in a microwave.","startMs":190460,"endMs":197180},{"speaker":"Pippa","text":"That''s a lot quicker and easier than cooking from scratch – an idiom meaning to do something from the very beginning without using anything that''s already been made.","startMs":197180,"endMs":206820},{"speaker":"Phil","text":"Even though ultra-processed foods are often unhealthy, they taste good.","startMs":207240,"endMs":212260},{"speaker":"Phil","text":"That''s why Annabel calls chocolate her guilty pleasure.","startMs":212740,"endMs":215980},{"speaker":"Phil","text":"A guilty pleasure is something you enjoy but think you shouldn''t and feel a little embarrassed about.","startMs":216380,"endMs":222820},{"speaker":"Pippa","text":"Ultra-processed food is a tricky topic.","startMs":223260,"endMs":225820},{"speaker":"Pippa","text":"We know these foods have been linked to poor health, but at the same time they''re cheap, convenient and taste good.","startMs":226260,"endMs":233320},{"speaker":"Pippa","text":"So, what should we do?","startMs":233740,"endMs":235180},{"speaker":"Pippa","text":"Here''s Hannah and Annabel discussing this for BBC programme What in the World:","startMs":235600,"endMs":239780},{"speaker":"Hannah Gelbart","text":"Is it OK for me to have a packet of crisps once in a while?","startMs":240220,"endMs":243120},{"speaker":"Hannah Gelbart","text":"Should we be cutting ultra-processed foods out of our diets completely, or is there a way for us to still enjoy them from time to time?","startMs":243340,"endMs":250440},{"speaker":"Annabel Rackham","text":"I think the best thing to do is just not to panic.","startMs":250440,"endMs":253280},{"speaker":"Annabel Rackham","text":"Everything is fine in moderation.","startMs":253780,"endMs":255620},{"speaker":"Phil","text":"Hannah asks if it''s OK to eat ultra-processed foods once in a while, or from time to time.","startMs":256220,"endMs":262320},{"speaker":"Phil","text":"The phrases once in a while and from time to time mean occasionally – sometimes, but not very often.","startMs":262880,"endMs":270560},{"speaker":"Pippa","text":"Annabel replies using the phrase everything in moderation, which advises us that it''s best to avoid too much of anything.","startMs":271020,"endMs":278940},{"speaker":"Phil","text":"That sounds sensible to me, and it also means I won''t feel bad about eating chocolate now and then.","startMs":279300,"endMs":284640},{"speaker":"Phil","text":"Pippa, it''s time to reveal the answer to my question.","startMs":286540,"endMs":289780},{"speaker":"Phil","text":"Now, I asked you when fizzy drinks were invented.","startMs":289940,"endMs":295000},{"speaker":"Phil","text":"I''m afraid the correct answer was 1772.","startMs":297900,"endMs":301260},{"speaker":"Phil","text":"Apparently carbonated water was used to try to prevent scurvy on sea voyages.","startMs":301900,"endMs":307140},{"speaker":"Pippa","text":"Wow, that is amazing.","startMs":307520,"endMs":309360},{"speaker":"Pippa","text":"I wouldn''t have thought it was that long ago.","startMs":309540,"endMs":311760},{"speaker":"Phil","text":"Let''s recap the vocabulary we''ve learned, starting with ready meal – a meal from a supermarket that has already been prepared so you can heat it up quickly.","startMs":312840,"endMs":321260},{"speaker":"Pippa","text":"If you do something from scratch, you do it from the very beginning, without using anything that''s already been made.","startMs":321760,"endMs":328320},{"speaker":"Phil","text":"A guilty pleasure is something you enjoy but feel guilty or embarrassed about because you think you shouldn''t do it.","startMs":328980,"endMs":335980},{"speaker":"Pippa","text":"The phrases once in a while and from time to time mean occasionally, not very often.","startMs":336540,"endMs":342360},{"speaker":"Phil","text":"And finally, the phrase everything in moderation is used to advise someone that it''s best to avoid too much of anything.","startMs":342860,"endMs":350560},{"speaker":"Phil","text":"Once again, our six minutes are up, but if you''re hungry for more, head over to our website, bbclearningenglish.","startMs":351460,"endMs":358820},{"speaker":"Phil","text":"com, for more tasty topics and useful vocabulary.","startMs":358820,"endMs":361980},{"speaker":"Phil","text":"But for now, it''s goodbye.","startMs":363780,"endMs":365200},{"speaker":"Pippa","text":"Bye!","startMs":365640,"endMs":365980}]'::jsonb,
  'Understand and discuss should we eat ultra-processed food? using BBC natural English. You''ll pick up useful words like ultra-processed food, ingredient, additive. Listen to BBC 6 Minute English talk it through in natural English.',
  '["If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners.","Ultra-processed foods are everywhere, from sliced bread to chocolate biscuits and crisps.","They might taste good, but the bad news is that ultra-processed foods have been linked to poor health."]'::jsonb,
  '[{"word":"ultra-processed food","phonetic":"","pos":"Noun phrase","translation":"ultra qayta ishlangan ovqat","definition":"food made industrially with many added ingredients","example":"If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners."},{"word":"ingredient","phonetic":"","pos":"Noun","translation":"masalliq","definition":"one of the foods used to make a dish","example":"If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners."},{"word":"additive","phonetic":"","pos":"Noun","translation":"qo‘shimcha modda","definition":"a substance added to food","example":"If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners."},{"word":"nutrition","phonetic":"","pos":"Noun","translation":"ovqatlanish","definition":"the food and substances people need to be healthy","example":"If you''ve eaten anything today, then it''s likely that some of your food was ultra- processed – food containing artificial ingredients like additives and sweeteners."},{"word":"diet","phonetic":"","pos":"Noun","translation":"ratsion","definition":"the food someone usually eats","example":"Should we be cutting ultra-processed foods out of our diets completely, or is there a way for us to still enjoy them from time to time?"},{"word":"health risk","phonetic":"","pos":"Noun phrase","translation":"sog‘liq uchun xavf","definition":"something that may harm health","example":"They might taste good, but the bad news is that ultra-processed foods have been linked to poor health."}]'::jsonb,
  '[{"type":"mc","question":"What does \"ultra-processed food\" mean in this lesson?","options":["food made industrially with many added ingredients","one of the foods used to make a dish","a substance added to food","the food and substances people need to be healthy"],"correct":0,"explanation":"\"ultra-processed food\" means: food made industrially with many added ingredients"},{"type":"mc","question":"What does \"ingredient\" mean in this lesson?","options":["food made industrially with many added ingredients","a substance added to food","the food and substances people need to be healthy","one of the foods used to make a dish"],"correct":3,"explanation":"\"ingredient\" means: one of the foods used to make a dish"},{"type":"mc","question":"What does \"additive\" mean in this lesson?","options":["one of the foods used to make a dish","the food and substances people need to be healthy","a substance added to food","food made industrially with many added ingredients"],"correct":2,"explanation":"\"additive\" means: a substance added to food"},{"type":"mc","question":"What does \"nutrition\" mean in this lesson?","options":["a substance added to food","the food and substances people need to be healthy","food made industrially with many added ingredients","one of the foods used to make a dish"],"correct":1,"explanation":"\"nutrition\" means: the food and substances people need to be healthy"}]'::jsonb,
  'Understand and discuss should we eat ultra-processed food? using BBC natural English. What''s one thing from this lesson you could use in your own conversations this week?'
) on conflict (content_item_id) do update set transcript = excluded.transcript, summary = excluded.summary, takeaways = excluded.takeaways, vocabulary = excluded.vocabulary, quiz = excluded.quiz, reflection = excluded.reflection;

